INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (42, 'Mysql中文乱码问题解决', '项目jdbc获取数据库数据，中文乱码；这里给出一些解决方案：第一种，修改Mysql数据库编码，改成utf-8，默认是latin1 （推荐）； 如图，找到mysql安装，点mysql实例配置  一直点next知道下面这个界面：记住，前面那个圈 一点要点。。下拉框选utf8继续next直到：写你原来的密码继续，然', '2018-02-02 13:29:33', 343, 0, '<p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\">项目jdbc获取数据库数据，中文乱码；</p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><br/></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\">这里给出一些解决方案：</p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><br/></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><span style=\"color: rgb(255, 0, 0);\">第一种，修改Mysql数据库编码，改成utf-8，默认是latin1 （推荐）；</span></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><img alt=\"QQ鍥剧墖20160202132103.png\" src=\"/static/userImages/20160202/1454390480343030776.png\" title=\"1454390480343030776.png\"/> 如图，找到mysql安装，点mysql实例配置</p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><br/></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><img src=\"/static/userImages/20160202/1454390537171022264.jpg\" alt=\"1454390537171022264.jpg\"/></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\">&nbsp;</p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\">&nbsp;一直点next知道下面这个界面：</p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><img alt=\"QQ鍥剧墖20160202132310.png\" src=\"/static/userImages/20160202/1454390616812058607.png\" title=\"1454390616812058607.png\"/></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\">记住，前面那个圈 一点要点。。下拉框选utf8</p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><br/></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\">继续next直到：</p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><img alt=\"QQ鍥剧墖20160202132431.png\" src=\"/static/userImages/20160202/1454390692687028654.png\" title=\"1454390692687028654.png\"/></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\">写你原来的密码继续，然后继续Next:</p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><img alt=\"QQ鍥剧墖20160202132517.png\" src=\"/static/userImages/20160202/1454390731515038389.png\" title=\"1454390731515038389.png\"/></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\">点击 执行</p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><img alt=\"QQ鍥剧墖20160202132618.png\" src=\"/static/userImages/20160202/1454390793796097934.png\" title=\"1454390793796097934.png\"/></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\">这样就OK了；</p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><br/></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\">这个执行完。记得要把原来导入的项目数据库删除，重新的导入下即可；<br/></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><br/><span style=\"color: rgb(255, 0, 0);\"></span></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\"><span style=\"color: rgb(255, 0, 0);\">第二种，修改jdbc请求url 指定编码 （不推荐）<br/></span></p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\">在jdbc url后面 加上 ?useUnicode=true&amp;characterEncoding=UTF8 指定下编码；</p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\">假如是在xml配置文件里 要转义下 搞成 ?useUnicode=true&amp;amp;characterEncoding=UTF-8 ；</p><p style=\"margin: 5px 0px; color: rgb(0, 0, 0); font-family: sans-serif; font-size: 16px; font-style: normal; font-variant: normal; font-weight: normal; letter-spacing: normal; line-height: normal; orphans: auto; text-align: start; text-indent: 0px; text-transform: none; white-space: normal; widows: 1; word-spacing: 0px; -webkit-text-stroke-width: 0px;\">比如在spring配置文件里：</p><pre class=\"brush:xml;toolbar:false\">&lt;!--&nbsp;配置数据源&nbsp;--&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&lt;bean&nbsp;id=&quot;dataSource&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;class=&quot;com.alibaba.druid.pool.DruidDataSource&quot;&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;property&nbsp;name=&quot;url&quot;&nbsp;value=&quot;jdbc:mysql://localhost:3306/db_blog?useUnicode=true&amp;amp;characterEncoding=UTF-8&quot;/&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;property&nbsp;name=&quot;username&quot;&nbsp;value=&quot;root&quot;/&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;property&nbsp;name=&quot;password&quot;&nbsp;value=&quot;123456&quot;/&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&lt;/bean&gt;</pre><p><br/></p><p>推荐第一种；</p><p><br/></p>', 2, 'mysql 乱码');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (43, '解决Url带中文参数乱码问题', ' 这里我来介绍下如何配置Tomcat 来解决Url带中文参数乱码问题；首先打开Tomcat安装目录，以Tomcat7为例，其他版本基本一样；打开conf文件打开server.xml大概在70行左右的位置 我们加一个属性 URIEncoding=\"UTF-8\"搞成这样即可。。这个是发布项目的时候，配置方式。下面', '2018-01-22 13:38:39', 392, 0, '<p><img src=\"http://img.baidu.com/hi/jx2/j_0001.gif\"/> 这里我来介绍下如何配置Tomcat 来解决Url带中文参数乱码问题；</p><p><br/></p><p>首先打开Tomcat安装目录，以Tomcat7为例，其他版本基本一样；</p><p><img src=\"/static/userImages/20160202/1454391117593077429.jpg\" alt=\"1454391117593077429.jpg\"/></p><p><br/></p><p>打开conf文件</p><p><img src=\"/static/userImages/20160202/1454391166890014358.jpg\" alt=\"1454391166890014358.jpg\"/><br/></p><p><br/></p><p>打开server.xml</p><p><img src=\"/static/userImages/20160202/1454391299968024532.jpg\" alt=\"1454391299968024532.jpg\"/><br/></p><p><br/></p><p>大概在70行左右的位置 我们加一个属性 URIEncoding=&quot;UTF-8&quot;</p><p><br/></p><p><img src=\"/static/userImages/20160202/1454391361171014090.jpg\" alt=\"1454391361171014090.jpg\"/></p><p><br/></p><p>搞成这样即可。。这个是发布项目的时候，配置方式。</p><p><br/></p><p>下面介绍开发的时候，如何配置：</p><p>打开eclipse</p><p>找到server</p><p><img src=\"/static/userImages/20160202/1454391411687030232.jpg\" alt=\"1454391411687030232.jpg\"/><br/></p><p><br/></p><p>点开server.xml</p><p><img src=\"/static/userImages/20160202/1454391443968032571.jpg\" alt=\"1454391443968032571.jpg\"/><br/></p><p><br/></p><p>和刚才一样，加下 URIEncoding=&quot;UTF-8&quot; 这样就支持Url中文参数了；</p><p><br/></p><p>当然还有其他方法，比较麻烦。比如自己转码，过滤。这里就不介绍了。<br/></p>', 3, 'url中文参数');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (45, 'shiro介绍以及推荐视频教程', 'shiro是apache提供的强大而灵活的开源安全框架，它主要用来处理身份认证，授权，企业会话管理和加密。shiro功能：用户验证、用户执行访问权限控制、在任何环境下使用session API，如cs程序。可以使用多数据源如同时使用oracle、mysql。单点登录(sso)支持。remember me服务。', '2018-02-02 17:00:30', 562, 0, '<p>shiro是apache提供的强大而灵活的开源安全框架，它主要用来处理身份认证，授权，企业会话管理和加密。</p><p>shiro功能：用户验证、用户执行访问权限控制、在任何环境下使用session API，如cs程序。可以使用多数据源如同时使用oracle、mysql。单点登录(sso)支持。remember me服务。</p><p><br/></p><p>推荐视频教程 一头扎进shiro&nbsp;</p><p>课程目录：<span class=\"Apple-tab-span\" style=\"white-space: pre;\">	</span><a href=\"http://www.java1234.com/zy032.html\" target=\"_blank\" title=\"http://www.java1234.com/zy032.html\">http://www.java1234.com/zy032.html</a><span class=\"Apple-tab-span\" style=\"white-space: pre;\">	</span></p><p>百度云打包下载： &nbsp;<a href=\"http://pan.baidu.com/s/1ntEifgt\" target=\"_blank\" title=\"http://pan.baidu.com/s/1ntEifgt\">http://pan.baidu.com/s/1ntEifgt</a></p>', 7, 'shiro java');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (47, '什么是webservice?', '  webservice 有的人一看到这个，估计会认为这个是一种新技术，一种新框架。其实不是，严格的说，webservice是一种跨平台，跨语言的规范，用于不同平台，不同语言开发的应用之间的交互。  这里具体举个例子，比如在Windows Server服务器上有个C#.Net开发的应用A，在Linux上有个J', '2018-02-03 16:07:31', 461, 0, '<p>&nbsp; webservice 有的人一看到这个，估计会认为这个是一种新技术，一种新框架。<br/></p><p>其实不是，严格的说，webservice是一种跨平台，跨语言的规范，用于不同平台，不同语言开发的应用之间的交互。</p><p><br/></p><p>&nbsp; 这里具体举个例子，比如在Windows Server服务器上有个C#.Net开发的应用A，在Linux上有个Java语言开发的应用B，</p><p>B应用要调用A应用，或者是互相调用。用于查看对方的业务数据。</p><p>&nbsp; 再举个例子，天气预报接口。无数的应用需要获取天气预报信息；这些应用可能是各种平台，各种技术实现；而气象局的项目，估计也就一两种，要对外提供天气预报信息，这个时候，如何解决呢？</p><p><br/></p><p>&nbsp; webservice就是出于以上类似需求而定义出来的规范；</p><p>&nbsp;&nbsp;</p><p>&nbsp; 开发人员一般就是在具体平台开发webservice接口，以及调用webservice接口；每种开发语言都有自己的webservice实现框架。比如Java 就有&nbsp;Apache Axis1、Apache Axis2、Codehaus XFire、Apache CXF、Apache Wink、Jboss &nbsp;RESTEasyd等等...</p><p><br/></p><p><img src=\"/static/userImages/20160203/1454486847949023678.jpg\" title=\"1454486847949023678.jpg\" alt=\"20131203094415-1061627437.jpg\"/></p><p><br/></p><p><br/></p><p>&nbsp;&nbsp;</p>', 9, 'webservice java');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (51, '使用CXF开发WebService服务器端接口', 'CXF作为java领域主流的WebService实现框架，Java程序员有必要掌握它。CXF主页：http://cxf.apache.org/简介：百度百科今天的话，主要是用CXF来开发下WebService服务器端接口，明天写下开发客户端接口；这里用Maven。首先建一个Maven的j2se项目；项目的jr', '2018-02-14 20:46:04', 317, 0, '<p><br/>CXF作为java领域主流的WebService实现框架，Java程序员有必要掌握它。</p><p><br/></p><p>CXF主页：<a href=\"http://cxf.apache.org/\" target=\"_blank\" title=\"http://cxf.apache.org/\">http://cxf.apache.org/</a></p><p><br/></p><p>简介：<a href=\"http://baike.baidu.com/link?url=DSx84NVH4yZmYVYOiyFVucRScx5i1rXy5VH6N8VgLygZwkybqL1RVAISqgmWXt-pycDsWVTfydkOowd1ysGxGq\" target=\"_blank\" title=\"http://baike.baidu.com/link?url=DSx84NVH4yZmYVYOiyFVucRScx5i1rXy5VH6N8VgLygZwkybqL1RVAISqgmWXt-pycDsWVTfydkOowd1ysGxGq\">百度百科</a></p><p><br/></p><p>今天的话，主要是用CXF来开发下WebService服务器端接口，明天写下开发客户端接口；</p><p><br/></p><p>这里用Maven。<br/></p><p><br/></p><p>首先建一个Maven的j2se项目；<br/></p><p><img src=\"/static/userImages/20160214/1455452546687063197.jpg\" title=\"1455452546687063197.jpg\" alt=\"QQ鎴浘20160214201912.jpg\"/></p><p><br/></p><p>项目的jre用1.7，因为1.7有webservice的默认实现。不要用1.5 不然下面你用我的代码会有问题，用1.5的话，还需要另外加jar包，这里为了大家省事，要换成1.7;</p><p><img src=\"/static/userImages/20160214/1455452618468053349.jpg\" title=\"1455452618468053349.jpg\" alt=\"QQ鎴浘20160214201936.jpg\"/></p><p><br/></p><p><br/></p><p>根据规范，我们先建一个接口类：HelloWorld</p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice;\n\nimport&nbsp;javax.jws.WebService;\n\n@WebService\npublic&nbsp;interface&nbsp;HelloWorld&nbsp;{\n\n	public&nbsp;String&nbsp;say(String&nbsp;str);\n}</pre><p><br/></p><p>再建一个具体的实现类：HelloWorldImpl</p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice.impl;\n\nimport&nbsp;javax.jws.WebService;\n\nimport&nbsp;com.java1234.webservice.HelloWorld;\n\n@WebService\npublic&nbsp;class&nbsp;HelloWorldImpl&nbsp;implements&nbsp;HelloWorld{\n\n	public&nbsp;String&nbsp;say(String&nbsp;str)&nbsp;{\n		return&nbsp;&quot;Hello&nbsp;&quot;+str;\n	}\n\n}</pre><p><br/></p><p>最后建一个发布服务的主类：Server<br/></p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice;\n\n\nimport&nbsp;javax.xml.ws.Endpoint;\n\nimport&nbsp;com.java1234.webservice.impl.HelloWorldImpl;\n\npublic&nbsp;class&nbsp;Server&nbsp;{\n\n	public&nbsp;static&nbsp;void&nbsp;main(String[]&nbsp;args)&nbsp;{\n		System.out.println(&quot;web&nbsp;service&nbsp;start&quot;);&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;HelloWorld&nbsp;implementor&nbsp;=&nbsp;new&nbsp;HelloWorldImpl();&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;String&nbsp;address&nbsp;=&nbsp;&quot;http://192.168.1.103/helloWorld&quot;;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Endpoint.publish(address,&nbsp;implementor);&nbsp;&nbsp;//&nbsp;JDK实现\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;System.out.println(&quot;web&nbsp;service&nbsp;started&quot;);&nbsp;&nbsp;\n	}\n}</pre><p><br/></p><p>这里的Endpoint是Jdk自身实现的WebService。所以到这里我们不需要用到CXF的任何东西。</p><p>这里的address，写上自己的本机IP</p><p>我们运行下Server类：</p><p>运行效果如下：<br/></p><p><img src=\"/static/userImages/20160214/1455452954968056097.jpg\" title=\"1455452954968056097.jpg\" alt=\"QQ鎴浘20160214202633.jpg\"/></p><p><br/></p><p>我们在浏览器里访问：<a href=\"http://192.168.1.103/helloWorld?wsdl\" _src=\"http://192.168.1.103/helloWorld?wsdl\">http://192.168.1.103/helloWorld?wsdl</a> </p><p><br/></p><p>效果：<br/></p><p><img src=\"/static/userImages/20160214/1455453073062071044.jpg\" title=\"1455453073062071044.jpg\" alt=\"QQ鎴浘20160214202817.jpg\"/></p><p><br/></p><p>说明已经成功调用了webservice接口；</p><p><br/></p><p>这里的wsdl 是&nbsp;Web Services Description Language的缩写，是一个用来描述Web服务和说明如何与Web服务通信的XML语言。WSDL是Web Service的描述语言，用于描述Web Service的服务，接口绑定等，为用户提供详细的接口说明书。</p><p><br/></p><p>请求后得到的是一个xml规范文档。是一套规范，后面会具体介绍，任何语言平台技术都可以解析。</p><p><br/></p><p><br/></p><p><br/></p><p>下面我们介绍使用CXF来实现webservice接口：</p><p>我们先在pom.xml中加入：<br/></p><pre class=\"brush:xml;toolbar:false\">&lt;dependency&gt;\n		&lt;groupId&gt;org.apache.cxf&lt;/groupId&gt;\n		&lt;artifactId&gt;cxf-core&lt;/artifactId&gt;\n		&lt;version&gt;3.1.5&lt;/version&gt;\n	&lt;/dependency&gt;\n	\n	&lt;dependency&gt;\n		&lt;groupId&gt;org.apache.cxf&lt;/groupId&gt;\n		&lt;artifactId&gt;cxf-rt-frontend-jaxws&lt;/artifactId&gt;\n		&lt;version&gt;3.1.5&lt;/version&gt;\n	&lt;/dependency&gt;\n	\n	&lt;dependency&gt;\n		&lt;groupId&gt;org.apache.cxf&lt;/groupId&gt;\n		&lt;artifactId&gt;cxf-rt-transports-http-jetty&lt;/artifactId&gt;\n		&lt;version&gt;3.1.5&lt;/version&gt;\n	&lt;/dependency&gt;</pre><p><br/></p><p>这里要额外加入jetty，作为webservice发布的服务器。jetty是一个内嵌的web服务器；</p><p><br/></p><p><img src=\"/static/userImages/20160214/1455453479984038162.jpg\" title=\"1455453479984038162.jpg\" alt=\"QQ鎴浘20160214203514.jpg\"/></p><p><br/></p><p>我们把Server改下。换成CXF实现：<br/></p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice;\n\n\nimport&nbsp;org.apache.cxf.jaxws.JaxWsServerFactoryBean;\n\nimport&nbsp;com.java1234.webservice.impl.HelloWorldImpl;\n\npublic&nbsp;class&nbsp;Server&nbsp;{\n\n	public&nbsp;static&nbsp;void&nbsp;main(String[]&nbsp;args)&nbsp;{\n		System.out.println(&quot;web&nbsp;service&nbsp;start&quot;);&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;HelloWorld&nbsp;implementor&nbsp;=&nbsp;new&nbsp;HelloWorldImpl();&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;String&nbsp;address&nbsp;=&nbsp;&quot;http://192.168.1.103/helloWorld&quot;;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;//&nbsp;Endpoint.publish(address,&nbsp;implementor);&nbsp;&nbsp;//&nbsp;JDK实现\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;JaxWsServerFactoryBean&nbsp;factoryBean&nbsp;=&nbsp;new&nbsp;JaxWsServerFactoryBean();\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.setAddress(address);&nbsp;//&nbsp;设置暴露地址\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.setServiceClass(HelloWorld.class);&nbsp;//&nbsp;接口类\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.setServiceBean(implementor);&nbsp;//&nbsp;设置实现类\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.create();		\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;System.out.println(&quot;web&nbsp;service&nbsp;started&quot;);&nbsp;&nbsp;\n	}\n}</pre><p><br/></p><p>运行效果和刚才一样，这里就不再重复；</p><p><br/></p><p>完整源码下载：<a href=\"http://pan.baidu.com/s/1jHwGLF4\" target=\"_blank\" title=\"http://pan.baidu.com/s/1jHwGLF4\">http://pan.baidu.com/s/1jHwGLF4</a> </p><p><br/></p>', 9, 'webservice cxf java');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (52, '使用CXF开发WebService客户端', '前面一讲开发了webservice服务器端接口，今天的话，我们来开发webservice客户端，让大家来体验下过程；首先建一个Maven项目，项目名字，WS_Client；然后我们要用CXF给我们提供的工具wsdl2java 来根据请求的url生成客户端代码；wsdl2java工具在CXF开发包里；开发下载地', '2018-02-15 21:06:30', 332, 0, '<p>前面一讲开发了webservice服务器端接口，今天的话，我们来开发webservice客户端，让大家来体验下过程；</p><p><br/></p><p>首先建一个Maven项目，项目名字，WS_Client；</p><p><img src=\"/static/userImages/20160215/1455539511890048174.jpg\" alt=\"1455539511890048174.jpg\"/><br/></p><p><br/></p><p>然后我们要用CXF给我们提供的工具wsdl2java 来根据请求的url生成客户端代码；</p><p><br/></p><p>wsdl2java工具在CXF开发包里；</p><p>开发下载地址：<a title=\"http://cxf.apache.org/download.html\" target=\"_blank\" href=\"http://cxf.apache.org/download.html\">http://cxf.apache.org/download.html</a></p><p><img alt=\"QQ鎴浘20160215203213.jpg\" src=\"/static/userImages/20160215/1455539700734093102.jpg\" title=\"1455539700734093102.jpg\" width=\"667\" height=\"264\" style=\"width: 667px; height: 264px;\"/></p><p><br/></p><p>下载二进制包，然后解压到D盘 <br/></p><p><img alt=\"QQ鎴浘20160215203317.jpg\" src=\"/static/userImages/20160215/1455539761187019902.jpg\" title=\"1455539761187019902.jpg\"/></p><p><br/></p><p>这里我们看到了wsdl2java命令；当然要用的话，还得配置Path。我们打开环境变量配置，加入路径 D:\\apache-cxf-3.1.5\\bin&nbsp; 可能你的和我不一样；</p><p><img src=\"/static/userImages/20160215/1455539844625087079.jpg\" alt=\"1455539844625087079.jpg\"/><br/></p><p><br/></p><p>现在我们要干的事是在我们项目里生成我们需要的webservice客户端代码，</p><p>我们找到项目的本地路径，</p><p><img alt=\"QQ鎴浘20160215203622.jpg\" src=\"/static/userImages/20160215/1455539950421090821.jpg\" title=\"1455539950421090821.jpg\"/></p><p><br/></p><p>我的地址是：D:\\workspace\\WS_Client\\src\\main\\java 你们的可能和我不一样：</p><p><br/></p><p>然后我们进入dos，进入上面的本地硬盘地址，然后执行命令：wsdl2java&nbsp;<a href=\"http://192.168.1.103/helloWorld?wsdl\" _src=\"http://192.168.1.103/helloWorld?wsdl\">http://192.168.1.103/helloWorld?wsdl</a> </p><p><img src=\"/static/userImages/20160215/1455542517421041234.jpg\" title=\"1455542517421041234.jpg\" alt=\"QQ鎴浘20160215211824.jpg\"/></p><p><br/></p><p>这样就完成了代码的生成，我们刷新下工程：</p><p><img src=\"/static/userImages/20160215/1455542567125006252.jpg\" title=\"1455542567125006252.jpg\" alt=\"QQ鎴浘20160215212002.jpg\"/></p><p><br/></p><p>最关键的代码是HelloWorldService.java 我们下面写请求主类要用到；</p><p><br/></p><p><br/></p><p>我们下面写下主类 Client ，自己建下：</p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice;\n\npublic&nbsp;class&nbsp;Client&nbsp;{\n\n	public&nbsp;static&nbsp;void&nbsp;main(String[]&nbsp;args)&nbsp;{\n		HelloWorldService&nbsp;service=new&nbsp;HelloWorldService();\n		HelloWorld&nbsp;helloWorld=service.getHelloWorldPort();\n		System.out.println(helloWorld.say(&quot;java1234_小锋&quot;));\n	}\n}</pre><p><br/></p><p>运行如下：</p><p><img src=\"/static/userImages/20160215/1455542695984058850.jpg\" title=\"1455542695984058850.jpg\" alt=\"QQ鎴浘20160215212217.jpg\"/></p><p><br/></p><p>说明我们成功调用了webservice服务器端的接口。</p><p><br/></p><p>完整代码：<a href=\"http://pan.baidu.com/s/1gebOAR5\" target=\"_blank\" title=\"http://pan.baidu.com/s/1gebOAR5\">http://pan.baidu.com/s/1gebOAR5</a></p>', 9, 'webservice cxf');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (53, 'CXF处理JavaBean以及复合类型', '前面讲的是处理简单类型，今天这里来讲下CXF处理JavaBean以及复合类型，比如集合；这里实例是客户端传一个JavaBean，服务器端返回集合类型；在原来的项目实例基础上，我们先创建一个实体类User:package com.java1234.entity;/** * 用户实体类 * @author Adm', '2018-02-18 10:31:19', 214, 0, '<p>前面讲的是处理简单类型，今天这里来讲下CXF处理JavaBean以及复合类型，比如集合；</p><p><br/></p><p>这里实例是客户端传一个JavaBean，服务器端返回集合类型；</p><p><br/></p><p>在原来的项目实例基础上，我们先创建一个实体类User:<br/></p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.entity;\n\n/**\n&nbsp;*&nbsp;用户实体类\n&nbsp;*&nbsp;@author&nbsp;Administrator\n&nbsp;*\n&nbsp;*/\npublic&nbsp;class&nbsp;User&nbsp;{\n\n	private&nbsp;Integer&nbsp;id;&nbsp;//&nbsp;编号\n	private&nbsp;String&nbsp;userName;&nbsp;//&nbsp;用户名\n	private&nbsp;String&nbsp;password;&nbsp;//&nbsp;密码\n	\n	public&nbsp;Integer&nbsp;getId()&nbsp;{\n		return&nbsp;id;\n	}\n	public&nbsp;void&nbsp;setId(Integer&nbsp;id)&nbsp;{\n		this.id&nbsp;=&nbsp;id;\n	}\n	public&nbsp;String&nbsp;getUserName()&nbsp;{\n		return&nbsp;userName;\n	}\n	public&nbsp;void&nbsp;setUserName(String&nbsp;userName)&nbsp;{\n		this.userName&nbsp;=&nbsp;userName;\n	}\n	public&nbsp;String&nbsp;getPassword()&nbsp;{\n		return&nbsp;password;\n	}\n	public&nbsp;void&nbsp;setPassword(String&nbsp;password)&nbsp;{\n		this.password&nbsp;=&nbsp;password;\n	}\n	\n	\n}</pre><p><br/></p><p>再创建一个Role实体类：</p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.entity;\n\n/**\n&nbsp;*&nbsp;角色实体\n&nbsp;*&nbsp;@author&nbsp;Administrator\n&nbsp;*\n&nbsp;*/\npublic&nbsp;class&nbsp;Role&nbsp;{\n\n	private&nbsp;Integer&nbsp;id;&nbsp;//&nbsp;编号\n	private&nbsp;String&nbsp;roleName;&nbsp;//&nbsp;角色名称\n	\n	\n	\n	public&nbsp;Role()&nbsp;{\n		super();\n		//&nbsp;TODO&nbsp;Auto-generated&nbsp;constructor&nbsp;stub\n	}\n	\n	\n	\n	public&nbsp;Role(Integer&nbsp;id,&nbsp;String&nbsp;roleName)&nbsp;{\n		super();\n		this.id&nbsp;=&nbsp;id;\n		this.roleName&nbsp;=&nbsp;roleName;\n	}\n\n\n\n	public&nbsp;Integer&nbsp;getId()&nbsp;{\n		return&nbsp;id;\n	}\n	public&nbsp;void&nbsp;setId(Integer&nbsp;id)&nbsp;{\n		this.id&nbsp;=&nbsp;id;\n	}\n	public&nbsp;String&nbsp;getRoleName()&nbsp;{\n		return&nbsp;roleName;\n	}\n	public&nbsp;void&nbsp;setRoleName(String&nbsp;roleName)&nbsp;{\n		this.roleName&nbsp;=&nbsp;roleName;\n	}\n	\n	\n}</pre><p><br/></p><p><br/></p><p>然后HelloWorld再加一个接口方法getRoleByUser，通过用户查找角色：<br/></p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice;\n\nimport&nbsp;java.util.List;\n\nimport&nbsp;javax.jws.WebService;\n\nimport&nbsp;com.java1234.entity.Role;\nimport&nbsp;com.java1234.entity.User;\n\n@WebService\npublic&nbsp;interface&nbsp;HelloWorld&nbsp;{\n\n	public&nbsp;String&nbsp;say(String&nbsp;str);\n	\n	public&nbsp;List&lt;Role&gt;&nbsp;getRoleByUser(User&nbsp;user);\n}</pre><p><br/></p><p><br/></p><p>然后HelloWorld接口实现类 HelloWorldImpl写下新增的方法的具体实现，我们这里写死，模拟下即可：<br/></p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice.impl;\n\nimport&nbsp;java.util.ArrayList;\nimport&nbsp;java.util.List;\n\nimport&nbsp;javax.jws.WebService;\n\nimport&nbsp;com.java1234.entity.Role;\nimport&nbsp;com.java1234.entity.User;\nimport&nbsp;com.java1234.webservice.HelloWorld;\n\n@WebService\npublic&nbsp;class&nbsp;HelloWorldImpl&nbsp;implements&nbsp;HelloWorld{\n\n	public&nbsp;String&nbsp;say(String&nbsp;str)&nbsp;{\n		return&nbsp;&quot;Hello&nbsp;&quot;+str;\n	}\n\n	public&nbsp;List&lt;Role&gt;&nbsp;getRoleByUser(User&nbsp;user)&nbsp;{\n		List&lt;Role&gt;&nbsp;roleList=new&nbsp;ArrayList&lt;Role&gt;();\n		//&nbsp;模拟&nbsp;直接写死\n		if(user!=null){\n			if(user.getUserName().equals(&quot;java1234&quot;)&nbsp;&amp;&amp;&nbsp;user.getPassword().equals(&quot;123456&quot;)){\n				roleList.add(new&nbsp;Role(1,&quot;技术总监&quot;));\n				roleList.add(new&nbsp;Role(2,&quot;架构师&quot;));\n			}else&nbsp;if(user.getUserName().equals(&quot;jack&quot;)&nbsp;&amp;&amp;&nbsp;user.getPassword().equals(&quot;123456&quot;)){\n				roleList.add(new&nbsp;Role(3,&quot;程序员&quot;));\n			}\n			return&nbsp;roleList;\n		}else{\n			return&nbsp;null;			\n		}\n		\n	}\n	\n	\n\n}</pre><p><br/></p><p>服务端其他地方不用动；<br/></p><p><br/></p><p>下面我们来处理下客户端，和前面讲的一样。我们用wsdl2java工具重新生成代码，这里就不再讲；</p><p><br/></p><p><img src=\"/static/userImages/20160218/1455762437448028677.jpg\" title=\"1455762437448028677.jpg\" alt=\"QQ鎴浘20160218103035.jpg\"/></p><p><br/></p><p>这里我看到，实体类，以及接口实现，代码都生成了。</p><p><br/></p><p>我们改下Client类：</p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice;\n\nimport&nbsp;java.util.List;\n\npublic&nbsp;class&nbsp;Client&nbsp;{\n\n	public&nbsp;static&nbsp;void&nbsp;main(String[]&nbsp;args)&nbsp;{\n		HelloWorldService&nbsp;service=new&nbsp;HelloWorldService();\n		HelloWorld&nbsp;helloWorld=service.getHelloWorldPort();\n		//System.out.println(helloWorld.say(&quot;java1234&quot;));\n		User&nbsp;user=new&nbsp;User();\n		user.setUserName(&quot;jack&quot;);\n		user.setPassword(&quot;123456&quot;);\n		List&lt;Role&gt;&nbsp;roleList=helloWorld.getRoleByUser(user);\n		for(Role&nbsp;role:roleList){\n			System.out.println(role.getId()+&quot;,&quot;+role.getRoleName());\n		}\n	}\n}</pre><p><br/></p><p>运行截图：<br/></p><p><img src=\"/static/userImages/20160218/1455762521698070806.jpg\" title=\"1455762521698070806.jpg\" alt=\"QQ鎴浘20160218103159.jpg\"/></p><p><br/></p><p>完整代码：<a href=\"http://pan.baidu.com/s/1c1drMYO\" target=\"_blank\" title=\"http://pan.baidu.com/s/1c1drMYO\">http://pan.baidu.com/s/1c1drMYO</a></p><p><br/></p>', 9, 'webservice cxf');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (54, 'webservice执行过程深入理解', '前面我们搞了1，2个DEMO，基本对webservice服务发布，调用 ，执行 有一定的了解。今天的话，我们再系统的梳理下webservice执行过程。首先我们在webservice服务器端开发webservice接口，然后发布webservice；然后我们通过一个Url调用webservice接口，比如发布', '2018-03-19 20:18:54', 307, 0, '<p>前面我们搞了1，2个DEMO，基本对webservice服务发布，调用 ，执行 有一定的了解。</p><p>今天的话，我们再系统的梳理下webservice执行过程。</p><p><br/></p><p>首先我们在webservice服务器端开发webservice接口，然后发布webservice；</p><p><br/></p><p>然后我们通过一个Url调用webservice接口，比如发布的时候 ，url是&nbsp;http://192.168.1.103/helloWorld</p><p><br/></p><p>那我们请求的url就是&nbsp;http://192.168.1.103/helloWorld?wsdl &nbsp;</p><p><br/></p><p>我们在浏览器里输入，运行如下：</p><p><img src=\"/static/userImages/20160219/1455883676261078945.jpg\" title=\"1455883676261078945.jpg\" alt=\"QQ鎴浘20160219201122.jpg\"/></p><p><br/></p><p>这一大串xml标记，其实就是wsdl （Web Services Description Language） 也就是Web Service描述语言，描述服务器端定义的webservice接口的相关信息，</p><p>当然我们不用花时间去学习这东西，毕竟这东西是一套规范，但是我们仔细观察，猜测，也能分析出一些猫腻来，这里wsdl:types就是定义了一些变量，wsdl:message相当于定义方法，</p><p>wsdl:portType相当与调用与返回，下面的话，就是一些操作。这东西不必要去研究细节，搞这东西会晕死的。有工具给我处理。我们角度要站得高。</p><p><br/></p><p>客户端通过这个url请求，获得wsdl规范的xml文档片段信息，然后这里又涉及到一个新的概念SOAP（Simple Object Access Protocol）即简单对象访问协议，我们通过这个协议，来实现客户端，服务器端消息交互，SOAP使用XML消息调用远程方法；当然交互的媒介就是xml，具体交互内容根据wsdl文档描述来。</p><p><br/></p><p>这个就是大体的一个webservie执行过程。<img src=\"http://img.baidu.com/hi/jx2/j_0013.gif\"/> 当然，我作为一个开发者，我觉得一般的应用，Ajax跨域调用，以JSON作为交互媒介也不错。当然也要根据具体情况来。比如有大量的对象，集合类型，webservice还是有他的强项的。</p><p><br/></p><p><br/></p><p><br/></p>', 9, 'webservice cxf');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (56, 'cxf处理一些Map等复杂类型', '前面讲的一些都是简单类型,cxf都支持。但是有些复杂类型，cxf是不支持，比如常用的Map类型；下面我们在前面的实例基础上在加一个方法，比如我们现在有个需求，获取所有用用户以及对应的每个用户所有角色信息；服务器端：HelloWorld接口加方法：/**	 * 获取所有用户以及对应的角色	 * @return	', '2018-02-22 17:46:30', 196, 0, '<p>前面讲的一些都是简单类型,cxf都支持。但是有些复杂类型，cxf是不支持，比如常用的Map类型；<br/></p><p><br/></p><p>下面我们在前面的实例基础上在加一个方法，比如我们现在有个需求，获取所有用用户以及对应的每个用户所有角色信息；</p><p><br/></p><p>服务器端：<br/></p><p><br/></p><p>HelloWorld接口加方法：</p><pre class=\"brush:java;toolbar:false\">/**\n	&nbsp;*&nbsp;获取所有用户以及对应的角色\n	&nbsp;*&nbsp;@return\n	&nbsp;*/\n	public&nbsp;Map&lt;String,List&lt;Role&gt;&gt;&nbsp;getRoles();</pre><p><br/></p><p>HelloWorldImpl实现类加方法实现：<br/></p><pre class=\"brush:java;toolbar:false\">public&nbsp;Map&lt;String,&nbsp;List&lt;Role&gt;&gt;&nbsp;getRoles()&nbsp;{\n		Map&lt;String,List&lt;Role&gt;&gt;&nbsp;map=new&nbsp;HashMap&lt;String,List&lt;Role&gt;&gt;();\n		List&lt;Role&gt;&nbsp;roleList1=new&nbsp;ArrayList&lt;Role&gt;();\n		roleList1.add(new&nbsp;Role(1,&quot;技术总监&quot;));\n		roleList1.add(new&nbsp;Role(2,&quot;架构师&quot;));\n		map.put(&quot;java1234&quot;,&nbsp;roleList1);\n		List&lt;Role&gt;&nbsp;roleList2=new&nbsp;ArrayList&lt;Role&gt;();\n		roleList2.add(new&nbsp;Role(1,&quot;程序员&quot;));\n		map.put(&quot;jack&quot;,&nbsp;roleList2);\n		return&nbsp;map;\n	}</pre><p><br/></p><p>然后我们启动Server类：发现报错：</p><p><img src=\"/static/userImages/20160222/1456134575421042758.jpg\" title=\"1456134575421042758.jpg\" alt=\"QQ鎴浘20160222175231.jpg\"/></p><p>这个报错信息说，不支持该类型；</p><p><br/></p><p>这里我们有好几种解决方案，这里我们用最常用的一种，使用适配器，把cxf不能接受的类型通过适配器，转能接受的类型。</p><p><br/></p><p>我们使用@XmlJavaTypeAdapter注解，加在接口定义上，完整接口代码如下：</p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice;\n\nimport&nbsp;java.util.List;\nimport&nbsp;java.util.Map;\n\nimport&nbsp;javax.jws.WebService;\nimport&nbsp;javax.xml.bind.annotation.adapters.XmlJavaTypeAdapter;\n\nimport&nbsp;com.java1234.adapter.MapAdapter;\nimport&nbsp;com.java1234.entity.Role;\nimport&nbsp;com.java1234.entity.User;\n\n@WebService\npublic&nbsp;interface&nbsp;HelloWorld&nbsp;{\n\n	public&nbsp;String&nbsp;say(String&nbsp;str);\n	\n	public&nbsp;List&lt;Role&gt;&nbsp;getRoleByUser(User&nbsp;user);\n	\n	/**\n	&nbsp;*&nbsp;获取所有用户以及对应的角色\n	&nbsp;*&nbsp;@return\n	&nbsp;*/\n	@XmlJavaTypeAdapter(MapAdapter.class)\n	public&nbsp;Map&lt;String,List&lt;Role&gt;&gt;&nbsp;getRoles();\n}</pre><p><br/></p><p>这里参数需要一个实现了XmlAdapter类的适配器类；</p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.adapter;\n\nimport&nbsp;java.util.HashMap;\nimport&nbsp;java.util.List;\nimport&nbsp;java.util.Map;\n\nimport&nbsp;javax.xml.bind.annotation.adapters.XmlAdapter;\n\nimport&nbsp;com.java1234.entity.Role;\n\n/**\n&nbsp;*&nbsp;Map适配器\n&nbsp;*&nbsp;@author&nbsp;Administrator\n&nbsp;*\n&nbsp;*/\npublic&nbsp;class&nbsp;MapAdapter&nbsp;extends&nbsp;XmlAdapter&lt;MyRole[],&nbsp;Map&lt;String,List&lt;Role&gt;&gt;&gt;{\n\n	/**\n	&nbsp;*&nbsp;适配转换&nbsp;&nbsp;MyRole[]&nbsp;-&gt;&nbsp;Map&lt;String,&nbsp;List&lt;Role&gt;&gt;\n	&nbsp;*/\n	@Override\n	public&nbsp;Map&lt;String,&nbsp;List&lt;Role&gt;&gt;&nbsp;unmarshal(MyRole[]&nbsp;v)&nbsp;throws&nbsp;Exception&nbsp;{\n		Map&lt;String,&nbsp;List&lt;Role&gt;&gt;&nbsp;map=new&nbsp;HashMap&lt;String,List&lt;Role&gt;&gt;();\n		for(int&nbsp;i=0;i&lt;v.length;i++){\n			MyRole&nbsp;r=v[i];\n			map.put(r.getKey(),&nbsp;r.getValue());\n		}\n		return&nbsp;map;\n	}\n\n	/**\n	&nbsp;*&nbsp;适配转换&nbsp;&nbsp;Map&lt;String,&nbsp;List&lt;Role&gt;&gt;&nbsp;-&gt;&nbsp;MyRole[]\n	&nbsp;*/\n	@Override\n	public&nbsp;MyRole[]&nbsp;marshal(Map&lt;String,&nbsp;List&lt;Role&gt;&gt;&nbsp;v)&nbsp;throws&nbsp;Exception&nbsp;{\n		MyRole[]&nbsp;roles=new&nbsp;MyRole[v.size()];\n		int&nbsp;i=0;\n		for(String&nbsp;key:v.keySet()){\n			roles[i]=new&nbsp;MyRole();\n			roles[i].setKey(key);\n			roles[i].setValue(v.get(key));\n			i++;\n		}\n		return&nbsp;roles;\n	}\n\n	\n	\n\n}</pre><p>这里的话XmlAdapter要加两个参数，XmlAdapter&lt;ValueType,BoundType&gt;&nbsp;</p><p>ValueType是cxf能接收的类型，这里我用了数组；</p><p>BoundType是cxf不能接受的类型，也就是我例子里的需求的Map类型；</p><p><br/></p><p>这里大家会看到，还有一个MyRole自定义类型，key:value。我们搞成两个属性，具体实现如下：<br/></p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.adapter;\n\nimport&nbsp;java.util.List;\n\nimport&nbsp;com.java1234.entity.Role;\n\n/**\n&nbsp;*&nbsp;自定义实体&nbsp;cxf能接受\n&nbsp;*&nbsp;@author&nbsp;Administrator\n&nbsp;*\n&nbsp;*/\npublic&nbsp;class&nbsp;MyRole&nbsp;{\n\n	private&nbsp;String&nbsp;key;\n	private&nbsp;List&lt;Role&gt;&nbsp;value;\n	\n	public&nbsp;String&nbsp;getKey()&nbsp;{\n		return&nbsp;key;\n	}\n	public&nbsp;void&nbsp;setKey(String&nbsp;key)&nbsp;{\n		this.key&nbsp;=&nbsp;key;\n	}\n	public&nbsp;List&lt;Role&gt;&nbsp;getValue()&nbsp;{\n		return&nbsp;value;\n	}\n	public&nbsp;void&nbsp;setValue(List&lt;Role&gt;&nbsp;value)&nbsp;{\n		this.value&nbsp;=&nbsp;value;\n	}\n	\n	\n}</pre><p><br/></p><p>OK 这样就行了。我们运行Server类，发布webservice接口：</p><p><img src=\"/static/userImages/20160222/1456134226937065109.jpg\" title=\"1456134226937065109.jpg\" alt=\"QQ鎴浘20160222174638.jpg\"/></p><p><br/></p><p><br/></p><p>然后就到了webservice客户端，我们用wsdl2java工具生成下最新代码，具体过程前面讲过，这里不重复讲：</p><p>生成代码如下：</p><p><img src=\"/static/userImages/20160222/1456134312484067804.jpg\" title=\"1456134312484067804.jpg\" alt=\"QQ鎴浘20160222174813.jpg\"/></p><p><br/></p><p>我们修改下Client类：</p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice;\n\nimport&nbsp;java.util.List;\n\npublic&nbsp;class&nbsp;Client&nbsp;{\n\n	public&nbsp;static&nbsp;void&nbsp;main(String[]&nbsp;args)&nbsp;{\n		HelloWorldService&nbsp;service=new&nbsp;HelloWorldService();\n		HelloWorld&nbsp;helloWorld=service.getHelloWorldPort();\n		//System.out.println(helloWorld.say(&quot;java1234&quot;));\n		/*User&nbsp;user=new&nbsp;User();\n		user.setUserName(&quot;jack&quot;);\n		user.setPassword(&quot;123456&quot;);\n		List&lt;Role&gt;&nbsp;roleList=helloWorld.getRoleByUser(user);\n		for(Role&nbsp;role:roleList){\n			System.out.println(role.getId()+&quot;,&quot;+role.getRoleName());\n		}*/\n		MyRoleArray&nbsp;array=helloWorld.getRoles();\n		List&lt;MyRole&gt;&nbsp;roleList=array.item;\n		for(int&nbsp;i=0;i&lt;roleList.size();i++){\n			MyRole&nbsp;my=roleList.get(i);\n			System.out.print(my.key+&quot;:&quot;);\n			for(Role&nbsp;r:my.value){\n				System.out.print(r.getId()+&quot;,&quot;+r.getRoleName()+&quot;&nbsp;&quot;);\n			}\n			System.out.println();\n		}\n	}\n}</pre><p><br/></p><p>运行下:</p><p><img src=\"/static/userImages/20160222/1456134352140052359.jpg\" title=\"1456134352140052359.jpg\" alt=\"QQ鎴浘20160222174853.jpg\"/></p><p><br/></p><p>OK,这样就实现了复杂类型的调用；</p><p><br/></p><p>完整代码：<a href=\"http://pan.baidu.com/s/1kTUseOZ\" target=\"_blank\" title=\"http://pan.baidu.com/s/1kTUseOZ\">http://pan.baidu.com/s/1kTUseOZ</a></p>', 9, 'webservice cxf');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (58, '开发环境如何运行web项目不带项目名字', '比如有个项目Blog；默认情况下，我们发布到Tomcat，要运行项目。浏览器地址是这样的： http://localhost:8080/Blog但是某些情况，我们只有一个项目，而且需要直接IP加端口访问，这个时候，我们可以通过配置Eclipse里的Servers；比如Tomcat作为Web服务器，Eclips', '2018-02-24 18:42:23', 245, 0, '<p>比如有个项目Blog；</p><p><img src=\"/static/userImages/20160224/1456309931725025871.jpg\" alt=\"1456309931725025871.jpg\"/></p><p><br/></p><p>默认情况下，我们发布到Tomcat，要运行项目。浏览器地址是这样的： http://localhost:8080/Blog<br/></p><p><br/></p><p>但是某些情况，我们只有一个项目，而且需要直接IP加端口访问，这个时候，我们可以通过配置Eclipse里的Servers；</p><p>比如Tomcat作为Web服务器，Eclipse Package Explorer 视图下有 ：</p><p><br/></p><p><img src=\"/static/userImages/20160224/1456310119928082641.jpg\" alt=\"1456310119928082641.jpg\"/></p><p><br/></p><p>我们打开server.xml，我们在最下方可以看到一个Context节点：</p><p>&lt;Context docBase=&quot;Blog&quot; path=&quot;/Blog&quot; reloadable=&quot;true&quot; source=&quot;org.eclipse.jst.j2ee.server:Blog&quot;/&gt;&lt;/Host&gt;</p><p><br/></p><p>我们只需要把 path属性值改下，改成path=&quot;/&quot; 即可；</p><p><br/></p><p>改成 保存下； 我们就可以用 http://localhost:8080/ 来访问项目； 当然这里的端口也是可以修改的；</p><p><br/></p><p>我们找到Connector节点：&lt;Connector URIEncoding=&quot;UTF-8&quot; connectionTimeout=&quot;20000&quot; port=&quot;8080&quot; protocol=&quot;HTTP/1.1&quot; redirectPort=&quot;8443&quot;/&gt;</p><p>我们修改port即可 改成80 这样就不需要加端口了；（发布到互联网的项目，我们都要改成80端口）;</p><p>这里的 URIEncoding=&quot;UTF-8&quot;是我自己加的。主要解决url带中文参数问题，具体请看 <a _src=\"http://blog.java1234.com/blog/articles/43.html\" href=\"http://blog.java1234.com/blog/articles/43.html\">http://blog.java1234.com/blog/articles/43.html</a><br/></p><p><br/> </p><p><br/> </p>', 3, 'tomcat');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (59, '如何发布Web项目到互联网', '比如我们有个项目想要发布到互联网上，我们首先需要购买域名以及主机，主机的话，推荐云主机（本人推荐西部数码或者阿里云），性能好；我们先在云主机上搭建环境，比如Mysql，Jdk，Tomcat；然后我们把自己开发的项目打包，打成War包；具体操作；右击项目-> Export然后点击 Next ;选择Browse，', '2018-02-24 18:55:40', 504, 0, '<p>比如我们有个项目想要发布到互联网上，我们首先需要购买域名以及主机，主机的话，推荐云主机（本人推荐西部数码或者阿里云），性能好；</p><p>我们先在云主机上搭建环境，比如Mysql，Jdk，Tomcat；</p><p>然后我们把自己开发的项目打包，打成War包；</p><p>具体操作；右击项目-&gt; Export</p><p><img alt=\"QQ鎴浘20160224184605.jpg\" src=\"/static/userImages/20160224/1456310792100080598.jpg\" title=\"1456310792100080598.jpg\"/></p><p><br/></p><p>然后点击 Next ;</p><p><img alt=\"QQ鎴浘20160224184644.jpg\" src=\"/static/userImages/20160224/1456310837522027928.jpg\" title=\"1456310837522027928.jpg\"/></p><p><br/></p><p>选择Browse，我们随便选个地方&nbsp; 然后点击Finish即可；</p><p>这样我们就可以生成一个War包了；</p><p>我们把War包传到主机上去，放到Tomcat的webapps下，启动tomcat的startup.bat，会自动解压项目；</p><p>到了这里，还不够。我们只能通过 <a _src=\"http://外网IP:8080/项目名称访问；\" href=\"http://外网IP:8080/项目名称访问；\">http://外网IP:8080/项目名称访问；</a><br/></p><p>我们现在要干两个事情，第一个是去掉端口，第二个是去掉项目名称</p><p>我们找到tomcat安装包下的conf文件夹下的server.xml文件；</p><p><img alt=\"QQ鎴浘20160224185006.jpg\" src=\"/static/userImages/20160224/1456311055147010296.jpg\" title=\"1456311055147010296.jpg\"/></p><p>找到Connector节点；</p><pre class=\"brush:xml;toolbar:false\">&lt;Connector&nbsp;port=&quot;8080&quot;&nbsp;protocol=&quot;HTTP/1.1&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;connectionTimeout=&quot;20000&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;redirectPort=&quot;8443&quot;&nbsp;/&gt;</pre><p>我们把port=&quot;8080&quot;改成80端口即可，这样我们就可以不用端口了。不加端口就是默认访问80端口；</p><p><br/></p><p>我们在最后 找到Host节点：</p><pre class=\"brush:xml;toolbar:false\">&lt;Host&nbsp;name=&quot;localhost&quot;&nbsp;&nbsp;appBase=&quot;webapps&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;unpackWARs=&quot;true&quot;&nbsp;autoDeploy=&quot;true&quot;&gt;\n\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;!--&nbsp;SingleSignOn&nbsp;valve,&nbsp;share&nbsp;authentication&nbsp;between&nbsp;web&nbsp;applications\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Documentation&nbsp;at:&nbsp;/docs/config/valve.html&nbsp;--&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;!--\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;Valve&nbsp;className=&quot;org.apache.catalina.authenticator.SingleSignOn&quot;&nbsp;/&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;--&gt;\n\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;!--&nbsp;Access&nbsp;log&nbsp;processes&nbsp;all&nbsp;example.\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Documentation&nbsp;at:&nbsp;/docs/config/valve.html\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Note:&nbsp;The&nbsp;pattern&nbsp;used&nbsp;is&nbsp;equivalent&nbsp;to&nbsp;using&nbsp;pattern=&quot;common&quot;&nbsp;--&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;Valve&nbsp;className=&quot;org.apache.catalina.valves.AccessLogValve&quot;&nbsp;directory=&quot;logs&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;prefix=&quot;localhost_access_log.&quot;&nbsp;suffix=&quot;.txt&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;pattern=&quot;%h&nbsp;%l&nbsp;%u&nbsp;%t&nbsp;&amp;quot;%r&amp;quot;&nbsp;%s&nbsp;%b&quot;&nbsp;/&gt;\n\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;/Host&gt;</pre><p></p><p>我们在里面加一个节点：</p><p>&lt;Context path=&quot;&quot; docBase=&quot;C:\\apache-tomcat-7.0.11-windows-x86\\apache-tomcat-7.0.11\\webapps\\Blog&quot; debug=&quot;0&quot; reloadable=&quot;true&quot; /&gt;&nbsp;&nbsp; <br/></p><pre class=\"brush:xml;toolbar:false\">&lt;Host&nbsp;name=&quot;localhost&quot;&nbsp;&nbsp;appBase=&quot;webapps&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;unpackWARs=&quot;true&quot;&nbsp;autoDeploy=&quot;true&quot;&gt;\n\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;!--&nbsp;SingleSignOn&nbsp;valve,&nbsp;share&nbsp;authentication&nbsp;between&nbsp;web&nbsp;applications\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Documentation&nbsp;at:&nbsp;/docs/config/valve.html&nbsp;--&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;!--\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;Valve&nbsp;className=&quot;org.apache.catalina.authenticator.SingleSignOn&quot;&nbsp;/&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;--&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;Context&nbsp;path=&quot;&quot;&nbsp;docBase=&quot;C:\\apache-tomcat-7.0.11-windows-x86\\apache-tomcat-7.0.11\\webapps\\BaiduYun&quot;&nbsp;debug=&quot;0&quot;&nbsp;reloadable=&quot;true&quot;&nbsp;/&gt;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;!--&nbsp;Access&nbsp;log&nbsp;processes&nbsp;all&nbsp;example.\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Documentation&nbsp;at:&nbsp;/docs/config/valve.html\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Note:&nbsp;The&nbsp;pattern&nbsp;used&nbsp;is&nbsp;equivalent&nbsp;to&nbsp;using&nbsp;pattern=&quot;common&quot;&nbsp;--&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;Valve&nbsp;className=&quot;org.apache.catalina.valves.AccessLogValve&quot;&nbsp;directory=&quot;logs&quot;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;prefix=&quot;localhost_access_log.&quot;&nbsp;suffix=&quot;.txt&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;pattern=&quot;%h&nbsp;%l&nbsp;%u&nbsp;%t&nbsp;&amp;quot;%r&amp;quot;&nbsp;%s&nbsp;%b&quot;&nbsp;resolveHosts=&quot;false&quot;/&gt;\n\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;/Host&gt;</pre><p></p><p>这里的docBase要给成你的项目所在你服务器的本机的绝对路径；</p><p>其他不用变；</p><p><br/></p><p>项目数据库脚本的话自己导入下即可；这样就完整了项目部署；</p><p>我们可以直接通过外网IP直接访问项目；</p><p>域名解析下服务器外网IP。我们就可以通过域名访问了；</p><p><br/></p>', 3, 'tomcat');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (60, '如何找到Web项目编译好的class文件', '在某些情况，我们需要获取部分Eclipse里的项目编译好的class文件。这里我举个例子，比如我有一个web项目，已经发布到了互联网。但是有个小改动，我们只改了一个java类，这时候。我们不需要把项目重新打War包了，直接找到那个修改好的新产生的class文件，送到服务器，直接替换下原来的class文件即可，', '2018-02-25 08:10:32', 259, 0, '<p>在某些情况，我们需要获取部分Eclipse里的项目编译好的class文件。</p><p>这里我举个例子，比如我有一个web项目，已经发布到了互联网。但是有个小改动，我们只改了一个java类，这时候。我们不需要把项目重新打War包了，</p><p>直接找到那个修改好的新产生的class文件，送到服务器，直接替换下原来的class文件即可，</p><p>配置的Tomcat server.xml的时候 我们Context节点，要加reloadable=&quot;true&quot;，这样的话，Tomcat会自动重新启动项目，不需要我们人工的重启，很方便；</p><p>那如何找到Web项目编译好的class文件呢？</p><p>我们分两种项目进行讲解：</p><p>1，普通Web项目</p><p>我们首先找到Eclipse的工作空间 workspace；</p><p><img src=\"/static/userImages/20160225/1456358794413068531.jpg\" title=\"1456358794413068531.jpg\" alt=\"QQ鎴浘20160225080603.jpg\"/></p><p>这里的BaiduYunServer就是一个普通Web项目，我们点下文件夹，</p><p><img src=\"/static/userImages/20160225/1456358844069022109.jpg\" title=\"1456358844069022109.jpg\" alt=\"QQ鎴浘20160225080653.jpg\"/></p><p>里面有个build文件夹，这里就是项目编译的所有的class文件。</p><p><br/></p><p>2，Maven项目</p><p>我们还是首先找到Eclipse的工作空间 workspace；</p><p><img src=\"/static/userImages/20160225/1456358920038000713.jpg\" title=\"1456358920038000713.jpg\" alt=\"QQ鎴浘20160225080759.jpg\"/></p><p>这里的Blog项目，就是一个Maven项目，我们点下Blog；</p><p><img src=\"/static/userImages/20160225/1456358967319070308.jpg\" title=\"1456358967319070308.jpg\" alt=\"QQ鎴浘20160225080857.jpg\"/></p><p>这里有个target项目，里面就是Maven项目编译好的class文件，当然有配置文件的话，也会在里面；</p><p><br/></p><p>我们可以在里面找到我们需要的class文件；</p><p><br/></p>', 3, 'tomcat class文件');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (61, 'j2se项目如何打成可以运行Jar包', '经常有学员写完一个j2se项目来问我如何打成Jar包，很多学员自己摸索了。由于选错了一个选项，打出来的是Jar包，但不是可运行Jar包；今天我来讲下J2se项目如何打包成可运行Jar包；我们首先建一个J2se项目，随便取名 就叫Test算了：然后我们新建一个Java类 JFrameTest类代码如何：impo', '2018-02-26 21:18:25', 390, 0, '<p>经常有学员写完一个j2se项目来问我如何打成Jar包，很多学员自己摸索了。由于选错了一个选项，打出来的是Jar包，但不是可运行Jar包；<br/></p><p><br/></p><p>今天我来讲下J2se项目如何打包成可运行Jar包；</p><p><br/></p><p>我们首先建一个J2se项目，随便取名 就叫Test算了：</p><p>然后我们新建一个Java类&nbsp;JFrameTest</p><p><img src=\"/static/userImages/20160226/1456492304460084475.jpg\" title=\"1456492304460084475.jpg\" alt=\"QQ鎴浘20160226211111.jpg\"/></p><p><br/></p><p>类代码如何：</p><pre class=\"brush:java;toolbar:false\">import&nbsp;java.awt.Color;\n\nimport&nbsp;javax.swing.JFrame;\n\npublic&nbsp;class&nbsp;JFrameTest&nbsp;{\n\n	public&nbsp;static&nbsp;void&nbsp;main(String[]&nbsp;args)&nbsp;{\n		JFrame&nbsp;jFrame=new&nbsp;JFrame(&quot;JFrame窗体&quot;);\n		jFrame.getContentPane().setBackground(Color.RED);&nbsp;//&nbsp;设置容器的背景颜色\n		jFrame.setLocation(400,&nbsp;200);&nbsp;//&nbsp;设置容器的位置\n		jFrame.setSize(500,200);&nbsp;//&nbsp;设置容器大小\n		jFrame.setVisible(true);&nbsp;//&nbsp;让容器显示\n	}\n}</pre><p><br/></p><p>然后我们右击项目，选择 Export(导出)：</p><p><img src=\"/static/userImages/20160226/1456492376757021856.png\" title=\"1456492376757021856.png\" alt=\"QQ鍥剧墖20160226211216.png\"/></p><p><br/></p><p>下面就是重点了。一定要选择Runnable Jar file，可以运行Jar包； 选择第一个Jar file就坑了，那个是不可运行的Jar包；</p><p><br/></p><p>我们继续点Next ；</p><p><img src=\"/static/userImages/20160226/1456492463241086491.png\" title=\"1456492463241086491.png\" alt=\"QQ鍥剧墖20160226211347.png\"/></p><p><br/></p><p>这里 我们首先选择启动的包含main方法入口的主类，我们开发的j2se项目可能有好几个类里都包含main方法，我们要选入口的类（一般是登录的那个类）；</p><p>我们这里选择JFrameTest； 然后我们再点Browse(浏览)，导出的目标位置，就放桌面算了；</p><p><img src=\"/static/userImages/20160226/1456492597600055236.jpg\" title=\"1456492597600055236.jpg\" alt=\"QQ鎴浘20160226211544.jpg\"/></p><p><br/></p><p>最后我们选择Finish，我们会看到桌面会有一个Jar包；</p><p><img src=\"/static/userImages/20160226/1456492651772092576.jpg\" title=\"1456492651772092576.jpg\" alt=\"QQ鎴浘20160226211658.jpg\"/></p><p><br/></p><p>我们双击运行下，</p><p><img src=\"/static/userImages/20160226/1456492676600021293.jpg\" title=\"1456492676600021293.jpg\" alt=\"QQ鎴浘20160226211720.jpg\"/></p><p><br/></p><p>直接出结果。</p><p><br/></p><p><br/></p><p><br/></p>', 1, '打包');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (62, 'CXF添加拦截器', '今天开始讲下拦截器，前面大家学过servlet，struts2 都有拦截器概念，主要作用是做一些权限过滤，编码处理等；webservice也可以加上拦截器，我们可以给webservice请求加权限判断功能；webservice分服务端和客户端，服务端和客户端都是可以加拦截器的，无论是服务端还是客户端，都分进，', '2018-02-28 18:29:15', 278, 0, '<p style=\"white-space: normal;\">今天开始讲下拦截器，前面大家学过servlet，struts2 都有拦截器概念，主要作用是做一些权限过滤，编码处理等；</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">webservice也可以加上拦截器，我们可以给webservice请求加权限判断功能；</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">webservice分服务端和客户端，服务端和客户端都是可以加拦截器的，无论是服务端还是客户端，都分进，出（In，Out）拦截器；</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">我们先来改下服务端的Server类：<br/></p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice;\n\nimport&nbsp;org.apache.cxf.interceptor.LoggingInInterceptor;\nimport&nbsp;org.apache.cxf.interceptor.LoggingOutInterceptor;\nimport&nbsp;org.apache.cxf.jaxws.JaxWsServerFactoryBean;\n\nimport&nbsp;com.java1234.webservice.impl.HelloWorldImpl;\n\npublic&nbsp;class&nbsp;Server&nbsp;{\n\n	public&nbsp;static&nbsp;void&nbsp;main(String[]&nbsp;args)&nbsp;{\n		System.out.println(&quot;web&nbsp;service&nbsp;start&quot;);&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;HelloWorld&nbsp;implementor&nbsp;=&nbsp;new&nbsp;HelloWorldImpl();&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;String&nbsp;address&nbsp;=&nbsp;&quot;http://192.168.1.103/helloWorld&quot;;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;JaxWsServerFactoryBean&nbsp;factoryBean&nbsp;=&nbsp;new&nbsp;JaxWsServerFactoryBean();\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.setAddress(address);&nbsp;//&nbsp;设置暴露地址\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.setServiceClass(HelloWorld.class);&nbsp;//&nbsp;接口类\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.setServiceBean(implementor);&nbsp;//&nbsp;设置实现类\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.getInInterceptors().add(new&nbsp;LoggingInInterceptor());&nbsp;//&nbsp;添加in拦截器&nbsp;日志拦截器\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.getOutInterceptors().add(new&nbsp;LoggingOutInterceptor());&nbsp;//&nbsp;添加out拦截器\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.create();		\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;System.out.println(&quot;web&nbsp;service&nbsp;started&quot;);&nbsp;&nbsp;\n	}\n}</pre><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">这里的话，我们通过factoryBean对象可以获取拦截器组，添加进或者出拦截器，这里有个经典的拦截器，我们开发的时候经常用，就是日志拦截器，</p><p style=\"white-space: normal;\">我们可以把客户端的请求，以及服务端返回的信息打印出来，可以打印控制台，也可以打印到执行文件；这里为了演示方便，直接搞无参的拦截器，</p><p style=\"white-space: normal;\">打印到控制台；&nbsp;</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">无论是自定义的拦截器，还是CXF自带的拦截器，都必须实现Interceptor接口。</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">我们执行下Server类：</p><p style=\"white-space: normal;\"><img src=\"http://blog.java1234.com/static/userImages/20160228/1456653585413038703.jpg\" title=\"1456653585413038703.jpg\" alt=\"QQ鎴浘20160228175925.jpg\"/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">然后我们再来执行下客户端的Client类，结果：</p><p style=\"white-space: normal;\"><img src=\"http://blog.java1234.com/static/userImages/20160228/1456653669428069419.jpg\" title=\"1456653669428069419.jpg\" alt=\"QQ鎴浘20160228180012.jpg\"/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">然后我们仔细观察Server端的控制台:</p><pre class=\"brush:java;toolbar:false\">web&nbsp;service&nbsp;start\n二月&nbsp;28,&nbsp;2016&nbsp;5:59:19&nbsp;下午&nbsp;org.apache.cxf.wsdl.service.factory.ReflectionServiceFactoryBean&nbsp;buildServiceFromClass\n信息:&nbsp;Creating&nbsp;Service&nbsp;{http://webservice.java1234.com/}HelloWorldService&nbsp;from&nbsp;class&nbsp;com.java1234.webservice.HelloWorld\n二月&nbsp;28,&nbsp;2016&nbsp;5:59:20&nbsp;下午&nbsp;org.apache.cxf.endpoint.ServerImpl&nbsp;initDestination\n信息:&nbsp;Setting&nbsp;the&nbsp;server&#39;s&nbsp;publish&nbsp;address&nbsp;to&nbsp;be&nbsp;http://192.168.1.103:80/helloWorld\nSLF4J:&nbsp;Failed&nbsp;to&nbsp;load&nbsp;class&nbsp;&quot;org.slf4j.impl.StaticLoggerBinder&quot;.\nSLF4J:&nbsp;Defaulting&nbsp;to&nbsp;no-operation&nbsp;(NOP)&nbsp;logger&nbsp;implementation\nSLF4J:&nbsp;See&nbsp;http://www.slf4j.org/codes.html#StaticLoggerBinder&nbsp;for&nbsp;further&nbsp;details.\nweb&nbsp;service&nbsp;started\n二月&nbsp;28,&nbsp;2016&nbsp;6:00:07&nbsp;下午&nbsp;org.apache.cxf.services.HelloWorldService.HelloWorldPort.HelloWorld\n信息:&nbsp;Inbound&nbsp;Message\n----------------------------\nID:&nbsp;1\nAddress:&nbsp;http://192.168.1.103/helloWorld?wsdl\nHttp-Method:&nbsp;GET\nContent-Type:&nbsp;\nHeaders:&nbsp;{Accept=[text/html,&nbsp;image/gif,&nbsp;image/jpeg,&nbsp;*;&nbsp;q=.2,&nbsp;*/*;&nbsp;q=.2],&nbsp;connection=[keep-alive],&nbsp;Content-Type=[null],&nbsp;Host=[192.168.1.103],&nbsp;User-Agent=[Java/1.7.0_67]}\n--------------------------------------\n二月&nbsp;28,&nbsp;2016&nbsp;6:00:07&nbsp;下午&nbsp;org.apache.cxf.services.HelloWorldService.HelloWorldPort.HelloWorld\n信息:&nbsp;Inbound&nbsp;Message\n----------------------------\nID:&nbsp;2\nAddress:&nbsp;http://192.168.1.103/helloWorld\nEncoding:&nbsp;UTF-8\nHttp-Method:&nbsp;POST\nContent-Type:&nbsp;text/xml;&nbsp;charset=UTF-8\nHeaders:&nbsp;{Accept=[text/xml,&nbsp;multipart/related],&nbsp;connection=[keep-alive],&nbsp;Content-Length=[175],&nbsp;content-type=[text/xml;&nbsp;charset=UTF-8],&nbsp;Host=[192.168.1.103],&nbsp;SOAPAction=[&quot;&quot;],&nbsp;User-Agent=[JAX-WS&nbsp;RI&nbsp;2.2.4-b01]}\nPayload:&nbsp;&lt;?xml&nbsp;version=&quot;1.0&quot;&nbsp;?&gt;&lt;S:Envelope&nbsp;xmlns:S=&quot;http://schemas.xmlsoap.org/soap/envelope/&quot;&gt;&lt;S:Body&gt;&lt;ns2:getRoles&nbsp;xmlns:ns2=&quot;http://webservice.java1234.com/&quot;/&gt;&lt;/S:Body&gt;&lt;/S:Envelope&gt;\n--------------------------------------\n二月&nbsp;28,&nbsp;2016&nbsp;6:00:07&nbsp;下午&nbsp;org.apache.cxf.services.HelloWorldService.HelloWorldPort.HelloWorld\n信息:&nbsp;Outbound&nbsp;Message\n---------------------------\nID:&nbsp;2\nResponse-Code:&nbsp;200\nEncoding:&nbsp;UTF-8\nContent-Type:&nbsp;text/xml\nHeaders:&nbsp;{}\nPayload:&nbsp;&lt;soap:Envelope&nbsp;xmlns:soap=&quot;http://schemas.xmlsoap.org/soap/envelope/&quot;&gt;&lt;soap:Body&gt;&lt;ns2:getRolesResponse&nbsp;xmlns:ns2=&quot;http://webservice.java1234.com/&quot;&gt;&lt;return&gt;&lt;item&gt;&lt;key&gt;jack&lt;/key&gt;&lt;value&gt;&lt;id&gt;1&lt;/id&gt;&lt;roleName&gt;程序员&lt;/roleName&gt;&lt;/value&gt;&lt;/item&gt;&lt;item&gt;&lt;key&gt;java1234&lt;/key&gt;&lt;value&gt;&lt;id&gt;1&lt;/id&gt;&lt;roleName&gt;技术总监&lt;/roleName&gt;&lt;/value&gt;&lt;value&gt;&lt;id&gt;2&lt;/id&gt;&lt;roleName&gt;架构师&lt;/roleName&gt;&lt;/value&gt;&lt;/item&gt;&lt;/return&gt;&lt;/ns2:getRolesResponse&gt;&lt;/soap:Body&gt;&lt;/soap:Envelope&gt;\n--------------------------------------</pre><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">这里的打印出来的就是日志信息：Inbound 进信息 &nbsp;Outbound 是出信息，进的时候，大家会看到有个Headers SOAP消息。后面我们可以在里面加我们的数据；</p><p style=\"white-space: normal;\">在Outbound Message里，Payload消息里我们可以找到webservice返回的数据 SOAP消息；</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">同理，我们在客户端也可以加进出拦截器，修改Client代码：</p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice;\n\nimport&nbsp;java.util.List;\n\nimport&nbsp;org.apache.cxf.frontend.ClientProxy;\nimport&nbsp;org.apache.cxf.interceptor.LoggingInInterceptor;\nimport&nbsp;org.apache.cxf.interceptor.LoggingOutInterceptor;\n\npublic&nbsp;class&nbsp;Client&nbsp;{\n\n	public&nbsp;static&nbsp;void&nbsp;main(String[]&nbsp;args)&nbsp;{\n		HelloWorldService&nbsp;service=new&nbsp;HelloWorldService();\n		HelloWorld&nbsp;helloWorld=service.getHelloWorldPort();\n		org.apache.cxf.endpoint.Client&nbsp;client=ClientProxy.getClient(helloWorld);\n		client.getInInterceptors().add(new&nbsp;LoggingInInterceptor());&nbsp;//&nbsp;添加in拦截器&nbsp;日志拦截器\n		client.getOutInterceptors().add(new&nbsp;LoggingOutInterceptor());&nbsp;//&nbsp;添加out拦截器\n		//System.out.println(helloWorld.say(&quot;java1234&quot;));\n		/*User&nbsp;user=new&nbsp;User();\n		user.setUserName(&quot;jack&quot;);\n		user.setPassword(&quot;123456&quot;);\n		List&lt;Role&gt;&nbsp;roleList=helloWorld.getRoleByUser(user);\n		for(Role&nbsp;role:roleList){\n			System.out.println(role.getId()+&quot;,&quot;+role.getRoleName());\n		}*/\n		MyRoleArray&nbsp;array=helloWorld.getRoles();\n		List&lt;MyRole&gt;&nbsp;roleList=array.item;\n		for(int&nbsp;i=0;i&lt;roleList.size();i++){\n			MyRole&nbsp;my=roleList.get(i);\n			System.out.print(my.key+&quot;:&quot;);\n			for(Role&nbsp;r:my.value){\n				System.out.print(r.getId()+&quot;,&quot;+r.getRoleName()+&quot;&nbsp;&quot;);\n			}\n			System.out.println();\n		}\n	}\n}</pre><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">这里的话，我们用到了ClientProxy，客户端代理。</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">我们请求的时候，可以看到控制台的日志信息：</p><pre class=\"brush:java;toolbar:false\">二月&nbsp;28,&nbsp;2016&nbsp;6:22:53&nbsp;下午&nbsp;org.apache.cxf.wsdl.service.factory.ReflectionServiceFactoryBean&nbsp;buildServiceFromWSDL\n信息:&nbsp;Creating&nbsp;Service&nbsp;{http://webservice.java1234.com/}HelloWorldService&nbsp;from&nbsp;WSDL:&nbsp;http://192.168.1.103/helloWorld?wsdl\n二月&nbsp;28,&nbsp;2016&nbsp;6:22:53&nbsp;下午&nbsp;org.apache.cxf.services.HelloWorldService.HelloWorldPort.HelloWorld\n信息:&nbsp;Outbound&nbsp;Message\n---------------------------\nID:&nbsp;1\nAddress:&nbsp;http://192.168.1.103/helloWorld\nEncoding:&nbsp;UTF-8\nHttp-Method:&nbsp;POST\nContent-Type:&nbsp;text/xml\nHeaders:&nbsp;{Accept=[*/*],&nbsp;SOAPAction=[&quot;&quot;]}\nPayload:&nbsp;&lt;soap:Envelope&nbsp;xmlns:soap=&quot;http://schemas.xmlsoap.org/soap/envelope/&quot;&gt;&lt;soap:Body&gt;&lt;ns2:getRoles&nbsp;xmlns:ns2=&quot;http://webservice.java1234.com/&quot;/&gt;&lt;/soap:Body&gt;&lt;/soap:Envelope&gt;\n--------------------------------------\n二月&nbsp;28,&nbsp;2016&nbsp;6:22:53&nbsp;下午&nbsp;org.apache.cxf.services.HelloWorldService.HelloWorldPort.HelloWorld\n信息:&nbsp;Inbound&nbsp;Message\n----------------------------\nID:&nbsp;1\nResponse-Code:&nbsp;200\nEncoding:&nbsp;UTF-8\nContent-Type:&nbsp;text/xml;&nbsp;charset=UTF-8\nHeaders:&nbsp;{content-type=[text/xml;&nbsp;charset=UTF-8],&nbsp;Date=[Sun,&nbsp;28&nbsp;Feb&nbsp;2016&nbsp;10:22:53&nbsp;GMT],&nbsp;Server=[Jetty(9.2.11.v20150529)],&nbsp;transfer-encoding=[chunked]}\nPayload:&nbsp;&lt;soap:Envelope&nbsp;xmlns:soap=&quot;http://schemas.xmlsoap.org/soap/envelope/&quot;&gt;&lt;soap:Body&gt;&lt;ns2:getRolesResponse&nbsp;xmlns:ns2=&quot;http://webservice.java1234.com/&quot;&gt;&lt;return&gt;&lt;item&gt;&lt;key&gt;jack&lt;/key&gt;&lt;value&gt;&lt;id&gt;1&lt;/id&gt;&lt;roleName&gt;程序员&lt;/roleName&gt;&lt;/value&gt;&lt;/item&gt;&lt;item&gt;&lt;key&gt;java1234&lt;/key&gt;&lt;value&gt;&lt;id&gt;1&lt;/id&gt;&lt;roleName&gt;技术总监&lt;/roleName&gt;&lt;/value&gt;&lt;value&gt;&lt;id&gt;2&lt;/id&gt;&lt;roleName&gt;架构师&lt;/roleName&gt;&lt;/value&gt;&lt;/item&gt;&lt;/return&gt;&lt;/ns2:getRolesResponse&gt;&lt;/soap:Body&gt;&lt;/soap:Envelope&gt;\n--------------------------------------\njack:1,程序员&nbsp;\njava1234:1,技术总监&nbsp;2,架构师</pre><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">这里也是出进的日志信息，和上面那个类似；</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">OK到这里的话，添加拦截器已经讲完了；<br/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">完整代码：<a href=\"http://pan.baidu.com/s/1dEbs19Z\" target=\"_blank\" title=\"http://pan.baidu.com/s/1dEbs19Z\">http://pan.baidu.com/s/1dEbs19Z</a></p><p style=\"white-space: normal;\"><br/></p><p><br/></p>', 9, 'webservice cxf 拦截器');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (65, '部署Maven项目无法找到Maven管理的Jar包', '有些学员部署Maven项目的时候，经常遇到奇葩问题，就是导入了maven项目，也没报错，但是运行的时候，各种奇葩报错，xxx.class not found；等等；这种问题根源项目没有把maven管理的Jar包依赖进去；如何解决呢？这里给下解决方案：右击项目，-》 Properties -》 Deployme', '2018-03-03 12:41:53', 399, 0, '<p style=\"white-space: normal;\">有些学员部署Maven项目的时候，经常遇到奇葩问题，就是导入了maven项目，也没报错，但是运行的时候，各种奇葩报错，xxx.class not found；等等；<br/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">这种问题根源项目没有把maven管理的Jar包依赖进去；</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">如何解决呢？</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">这里给下解决方案：<br/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">右击项目，-》&nbsp;Properties -》&nbsp;Deployment Assembly</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\"><img src=\"http://blog.java1234.com/static/userImages/20160303/1456979882147011039.jpg\" title=\"1456979882147011039.jpg\" alt=\"QQ鎴浘20160303123627.jpg\"/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">我们点击 Add ;</p><p style=\"white-space: normal;\"><img src=\"http://blog.java1234.com/static/userImages/20160303/1456979944772024572.png\" title=\"1456979944772024572.png\" alt=\"QQ鍥剧墖20160303123803.png\"/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">选&nbsp;Java Build Path Entries &nbsp;然后 Next&nbsp;</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\"><img src=\"http://blog.java1234.com/static/userImages/20160303/1456979983616007611.jpg\" title=\"1456979983616007611.jpg\" alt=\"QQ鎴浘20160303123903.jpg\"/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">选&nbsp;maven Dependencies 然后点 &quot;Finish&quot; 即可；</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">这样就把Maven管理的Jar包依赖上去了；</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">假如还有其他小的报错。根据报错信息来解决即可，应该不是什么大问题了；</p><p style=\"white-space: normal;\"><br/></p><p><br/></p>', 12, 'maven 部署');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (69, 'CXF添加自定义拦截器', '前面我们说到CXF添加内置的拦截器，今天的话，我们来讲下如何添加自定义拦截器；我们的实例是客户端访问服务端webservice接口要加权限认证。我们思路先说下。我们可以通过在SOAP消息的Header头信息中添加自定义信息，然后发送到服务端端，服务器端通过获取Header头消息，然后进行认证；这里的添加消息，', '2018-03-14 09:54:13', 165, 0, '<p>前面我们说到CXF添加内置的拦截器，今天的话，我们来讲下如何添加自定义拦截器；</p><p><br/></p><p>我们的实例是客户端访问服务端webservice接口要加权限认证。</p><p><br/></p><p>我们思路先说下。我们可以通过在SOAP消息的Header头信息中添加自定义信息，然后发送到服务端端，服务器端通过获取</p><p>Header头消息，然后进行认证；这里的添加消息，和获取消息认证，我们都是通过自定义拦截器来实现；</p><p><br/></p><p>OK下面我们来实现下：</p><p><br/></p><p>首先是服务器端：</p><p><br/></p><p>我们自定义拦截器：MyInterceptor</p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.interceptor;\n\nimport&nbsp;java.util.List;\n\nimport&nbsp;org.apache.cxf.binding.soap.SoapMessage;\nimport&nbsp;org.apache.cxf.headers.Header;\nimport&nbsp;org.apache.cxf.interceptor.Fault;\nimport&nbsp;org.apache.cxf.phase.AbstractPhaseInterceptor;\nimport&nbsp;org.apache.cxf.phase.Phase;\nimport&nbsp;org.w3c.dom.Element;\nimport&nbsp;org.w3c.dom.NodeList;\n\n/**\n&nbsp;*&nbsp;自定义拦截器\n&nbsp;*&nbsp;@author&nbsp;Administrator\n&nbsp;*\n&nbsp;*/\npublic&nbsp;class&nbsp;MyInterceptor&nbsp;extends&nbsp;AbstractPhaseInterceptor&lt;SoapMessage&gt;{\n\n	public&nbsp;MyInterceptor(){\n		//&nbsp;在调用方法之前调用拦截器\n		super(Phase.PRE_INVOKE);\n	}\n\n	/**\n	&nbsp;*&nbsp;拦截获取消息\n	&nbsp;*/\n	public&nbsp;void&nbsp;handleMessage(SoapMessage&nbsp;message)&nbsp;throws&nbsp;Fault&nbsp;{\n		List&lt;Header&gt;&nbsp;headers=message.getHeaders();\n		if(headers==null&nbsp;||&nbsp;headers.size()==0){\n			throw&nbsp;new&nbsp;Fault(new&nbsp;IllegalArgumentException(&quot;没有Header,拦截器实施拦截&quot;));\n		}\n		Header&nbsp;firstHeader=headers.get(0);\n		Element&nbsp;ele=(Element)&nbsp;firstHeader.getObject();\n		NodeList&nbsp;userIds=ele.getElementsByTagName(&quot;userName&quot;);\n		NodeList&nbsp;userPasses=ele.getElementsByTagName(&quot;password&quot;);\n		\n		if(userIds.getLength()!=1){\n			throw&nbsp;new&nbsp;Fault(new&nbsp;IllegalArgumentException(&quot;用户名格式不对&quot;));\n		}\n		\n		if(userPasses.getLength()!=1){\n			throw&nbsp;new&nbsp;Fault(new&nbsp;IllegalArgumentException(&quot;密码格式不对&quot;));\n		}\n		\n		String&nbsp;userId=userIds.item(0).getTextContent();\n		String&nbsp;userPass=userPasses.item(0).getTextContent();\n		\n		if(!userId.equals(&quot;java1234&quot;)&nbsp;||&nbsp;!&nbsp;userPass.equals(&quot;123456&quot;)){\n			throw&nbsp;new&nbsp;Fault(new&nbsp;IllegalArgumentException(&quot;用户名或者密码不正确&quot;));\n		}\n		\n	}\n}</pre><p><br/></p><p>这里的话，我们主要是获取Header头消息，然后获取userName和password节点，然后获取值，进行权限判断，假如认证不通过，我们抛出异常；</p><p><br/></p><p>在Server类里，我们要添加一个in 拦截器，在进入的时候，我们要进行验证；<br/></p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice;\n\nimport&nbsp;org.apache.cxf.interceptor.LoggingInInterceptor;\nimport&nbsp;org.apache.cxf.interceptor.LoggingOutInterceptor;\nimport&nbsp;org.apache.cxf.jaxws.JaxWsServerFactoryBean;\n\nimport&nbsp;com.java1234.interceptor.MyInterceptor;\nimport&nbsp;com.java1234.webservice.impl.HelloWorldImpl;\n\npublic&nbsp;class&nbsp;Server&nbsp;{\n\n	public&nbsp;static&nbsp;void&nbsp;main(String[]&nbsp;args)&nbsp;{\n		System.out.println(&quot;web&nbsp;service&nbsp;start&quot;);&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;HelloWorld&nbsp;implementor&nbsp;=&nbsp;new&nbsp;HelloWorldImpl();&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;String&nbsp;address&nbsp;=&nbsp;&quot;http://10.10.7.18/helloWorld&quot;;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;JaxWsServerFactoryBean&nbsp;factoryBean&nbsp;=&nbsp;new&nbsp;JaxWsServerFactoryBean();\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.setAddress(address);&nbsp;//&nbsp;设置暴露地址\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.setServiceClass(HelloWorld.class);&nbsp;//&nbsp;接口类\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.setServiceBean(implementor);&nbsp;//&nbsp;设置实现类\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.getInInterceptors().add(new&nbsp;LoggingInInterceptor());&nbsp;//&nbsp;添加in拦截器&nbsp;日志拦截器\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.getOutInterceptors().add(new&nbsp;LoggingOutInterceptor());&nbsp;//&nbsp;添加out拦截器\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.getInInterceptors().add(new&nbsp;MyInterceptor());&nbsp;//&nbsp;添加自定义拦截器\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;factoryBean.create();		\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;System.out.println(&quot;web&nbsp;service&nbsp;started&quot;);&nbsp;&nbsp;\n	}\n}</pre><p><br/></p><p>接下来是修改客户端代码：</p><p>我们同样要添加一个自定义拦截器：AddHeaderInterceptor</p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.interceptor;\n\n\nimport&nbsp;java.util.List;\n\nimport&nbsp;javax.xml.namespace.QName;\n\nimport&nbsp;org.apache.cxf.binding.soap.SoapMessage;\nimport&nbsp;org.apache.cxf.headers.Header;\nimport&nbsp;org.apache.cxf.helpers.DOMUtils;\nimport&nbsp;org.apache.cxf.interceptor.Fault;\nimport&nbsp;org.apache.cxf.phase.AbstractPhaseInterceptor;\nimport&nbsp;org.apache.cxf.phase.Phase;\nimport&nbsp;org.w3c.dom.Document;\nimport&nbsp;org.w3c.dom.Element;\n\npublic&nbsp;class&nbsp;AddHeaderInterceptor&nbsp;extends&nbsp;AbstractPhaseInterceptor&lt;SoapMessage&gt;&nbsp;{\n\n	private&nbsp;String&nbsp;userName;\n	private&nbsp;String&nbsp;password;\n\n	public&nbsp;AddHeaderInterceptor(String&nbsp;userName,&nbsp;String&nbsp;password)&nbsp;{\n		super(Phase.PREPARE_SEND);&nbsp;//&nbsp;发送SOAP消息之前调用拦截器\n		this.userName=userName;\n		this.password=password;\n	}\n\n	public&nbsp;void&nbsp;handleMessage(SoapMessage&nbsp;message)&nbsp;throws&nbsp;Fault&nbsp;{\n		List&lt;Header&gt;&nbsp;headers=message.getHeaders();\n		\n		Document&nbsp;doc=DOMUtils.createDocument();\n		Element&nbsp;ele=doc.createElement(&quot;authHeader&quot;);\n		Element&nbsp;idElement=doc.createElement(&quot;userName&quot;);\n		idElement.setTextContent(userName);\n		Element&nbsp;passElement=doc.createElement(&quot;password&quot;);\n		passElement.setTextContent(password);\n		\n		ele.appendChild(idElement);\n		ele.appendChild(passElement);\n		\n		headers.add(new&nbsp;Header(new&nbsp;QName(&quot;java1234&quot;),ele));\n		\n		\n	}\n\n	\n}</pre><p><br/></p><p>这里的话，我们主要是在拦截器里创建头消息；</p><p><br/></p><p>Client类里我们要修改下，加下Out 拦截器：<br/></p><pre class=\"brush:java;toolbar:false\">package&nbsp;com.java1234.webservice;\n\nimport&nbsp;java.util.List;\n\nimport&nbsp;org.apache.cxf.frontend.ClientProxy;\nimport&nbsp;org.apache.cxf.interceptor.LoggingInInterceptor;\nimport&nbsp;org.apache.cxf.interceptor.LoggingOutInterceptor;\n\nimport&nbsp;com.java1234.interceptor.AddHeaderInterceptor;\n\npublic&nbsp;class&nbsp;Client&nbsp;{\n\n	public&nbsp;static&nbsp;void&nbsp;main(String[]&nbsp;args)&nbsp;{\n		HelloWorldService&nbsp;service=new&nbsp;HelloWorldService();\n		HelloWorld&nbsp;helloWorld=service.getHelloWorldPort();\n		org.apache.cxf.endpoint.Client&nbsp;client=ClientProxy.getClient(helloWorld);\n		//&nbsp;client.getInInterceptors().add(new&nbsp;LoggingInInterceptor());&nbsp;//&nbsp;添加in拦截器&nbsp;日志拦截器\n		client.getOutInterceptors().add(new&nbsp;AddHeaderInterceptor(&quot;java1234&quot;,&quot;123456&quot;));&nbsp;//&nbsp;添加自定义拦截器\n		client.getOutInterceptors().add(new&nbsp;LoggingOutInterceptor());&nbsp;//&nbsp;添加out拦截器\n		//System.out.println(helloWorld.say(&quot;java1234&quot;));\n		/*User&nbsp;user=new&nbsp;User();\n		user.setUserName(&quot;jack&quot;);\n		user.setPassword(&quot;123456&quot;);\n		List&lt;Role&gt;&nbsp;roleList=helloWorld.getRoleByUser(user);\n		for(Role&nbsp;role:roleList){\n			System.out.println(role.getId()+&quot;,&quot;+role.getRoleName());\n		}*/\n		MyRoleArray&nbsp;array=helloWorld.getRoles();\n		List&lt;MyRole&gt;&nbsp;roleList=array.item;\n		for(int&nbsp;i=0;i&lt;roleList.size();i++){\n			MyRole&nbsp;my=roleList.get(i);\n			System.out.print(my.key+&quot;:&quot;);\n			for(Role&nbsp;r:my.value){\n				System.out.print(r.getId()+&quot;,&quot;+r.getRoleName()+&quot;&nbsp;&quot;);\n			}\n			System.out.println();\n		}\n	}\n}</pre><p><br/></p><p>OK这样就完整了自定义拦截器实现权限认证；</p><p><br/></p><p>先运行Server类，和以前一样；</p><p><br/></p><p>假如我们把 &nbsp;client.getOutInterceptors().add(new AddHeaderInterceptor(&quot;java1234&quot;,&quot;123456&quot;)); // 添加自定义拦截器</p><p>密码改成 123&nbsp;</p><p><br/></p><p>然后运行Client类，会报错；</p><p><img src=\"/static/userImages/20160314/1457920424960022579.png\" title=\"1457920424960022579.png\" alt=\"QQ鎴浘20160314095323.png\"/></p><p><br/></p><p>用户名或者密码不正确；</p><p><br/></p><p>完整代码：&nbsp;<a href=\"http://pan.baidu.com/s/1dEaHNcX\" target=\"_blank\" title=\"http://pan.baidu.com/s/1dEaHNcX\">http://pan.baidu.com/s/1dEaHNcX</a></p><p><br/></p>', 9, 'webservice cxf');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (70, 'Spring整合CXF之发布WebService服务', '今天我们来讲下如何用Spring来整合CXF，来发布WebService服务；给下官方文档地址：http://cxf.apache.org/docs/writing-a-service-with-spring.html根据官方文档。我们把前面的实例用Spring整合CXF来处理下。会简化很多；首先我们来建一个', '2018-04-16 14:23:36', 195, 0, '<p style=\"white-space: normal;\">今天我们来讲下如何用Spring来整合CXF，来发布WebService服务；<br/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">给下官方文档地址：<a href=\"http://cxf.apache.org/docs/writing-a-service-with-spring.html\" target=\"_blank\" title=\"http://cxf.apache.org/docs/writing-a-service-with-spring.html\">http://cxf.apache.org/docs/writing-a-service-with-spring.html</a></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">根据官方文档。我们把前面的实例用Spring整合CXF来处理下。会简化很多；</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">首先我们来建一个Maven项目&nbsp;WebService_CXF</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">建好项目第一步，我们打开pom.xml</p><p style=\"white-space: normal;\">我们来添加下Spring支持：</p><pre class=\"brush:xml;toolbar:false\">&lt;!--&nbsp;添加Spring支持&nbsp;--&gt;\n&lt;dependency&gt;\n	&lt;groupId&gt;org.springframework&lt;/groupId&gt;\n	&lt;artifactId&gt;spring-core&lt;/artifactId&gt;\n	&lt;version&gt;4.1.7.RELEASE&lt;/version&gt;\n&lt;/dependency&gt;\n&lt;dependency&gt;\n	&lt;groupId&gt;org.springframework&lt;/groupId&gt;\n	&lt;artifactId&gt;spring-beans&lt;/artifactId&gt;\n	&lt;version&gt;4.1.7.RELEASE&lt;/version&gt;\n&lt;/dependency&gt;\n&lt;dependency&gt;\n	&nbsp;&lt;groupId&gt;org.springframework&lt;/groupId&gt;\n	&nbsp;&lt;artifactId&gt;spring-tx&lt;/artifactId&gt;\n	&nbsp;&lt;version&gt;4.1.7.RELEASE&lt;/version&gt;\n	&lt;/dependency&gt;\n&lt;dependency&gt;\n	&lt;groupId&gt;org.springframework&lt;/groupId&gt;\n	&lt;artifactId&gt;spring-context&lt;/artifactId&gt;\n	&lt;version&gt;4.1.7.RELEASE&lt;/version&gt;\n&lt;/dependency&gt;\n&lt;dependency&gt;\n	&lt;groupId&gt;org.springframework&lt;/groupId&gt;\n	&lt;artifactId&gt;spring-context-support&lt;/artifactId&gt;\n	&lt;version&gt;4.1.7.RELEASE&lt;/version&gt;\n&lt;/dependency&gt;\n\n&lt;dependency&gt;\n	&lt;groupId&gt;org.springframework&lt;/groupId&gt;\n	&lt;artifactId&gt;spring-web&lt;/artifactId&gt;\n	&lt;version&gt;4.1.7.RELEASE&lt;/version&gt;\n&lt;/dependency&gt;\n\n&lt;dependency&gt;\n	&lt;groupId&gt;org.springframework&lt;/groupId&gt;\n	&lt;artifactId&gt;spring-webmvc&lt;/artifactId&gt;\n	&lt;version&gt;4.1.7.RELEASE&lt;/version&gt;\n&lt;/dependency&gt;\n\n&lt;dependency&gt;\n	&lt;groupId&gt;org.springframework&lt;/groupId&gt;\n	&lt;artifactId&gt;spring-aop&lt;/artifactId&gt;\n	&lt;version&gt;4.1.7.RELEASE&lt;/version&gt;\n&lt;/dependency&gt;\n\n\n&lt;dependency&gt;\n	&lt;groupId&gt;org.springframework&lt;/groupId&gt;\n	&lt;artifactId&gt;spring-aspects&lt;/artifactId&gt;\n	&lt;version&gt;4.1.7.RELEASE&lt;/version&gt;\n&lt;/dependency&gt;\n\n&lt;dependency&gt;\n	&lt;groupId&gt;org.springframework&lt;/groupId&gt;\n	&lt;artifactId&gt;spring-jdbc&lt;/artifactId&gt;\n	&lt;version&gt;4.1.7.RELEASE&lt;/version&gt;\n&lt;/dependency&gt;</pre><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">接下来添加下CXF支持：</p><pre class=\"brush:xml;toolbar:false\">&lt;!--&nbsp;添加cxf支持&nbsp;&nbsp;--&gt;\n&lt;dependency&gt;\n	&lt;groupId&gt;org.apache.cxf&lt;/groupId&gt;\n	&lt;artifactId&gt;cxf-core&lt;/artifactId&gt;\n	&lt;version&gt;3.1.5&lt;/version&gt;\n&lt;/dependency&gt;\n\n&lt;dependency&gt;\n	&lt;groupId&gt;org.apache.cxf&lt;/groupId&gt;\n	&lt;artifactId&gt;cxf-rt-frontend-jaxws&lt;/artifactId&gt;\n	&lt;version&gt;3.1.5&lt;/version&gt;\n&lt;/dependency&gt;\n\n&lt;dependency&gt;\n	&lt;groupId&gt;org.apache.cxf&lt;/groupId&gt;\n	&lt;artifactId&gt;cxf-rt-transports-http&lt;/artifactId&gt;\n	&lt;version&gt;3.1.5&lt;/version&gt;\n&lt;/dependency&gt;</pre><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">我们在项目里添加下&nbsp;applicationContext.xml spring配置文件 我们要额外添加下命名路径，因为我们要用新的标签；</p><pre class=\"brush:xml;toolbar:false\">&lt;beans&nbsp;xmlns=&quot;http://www.springframework.org/schema/beans&quot;&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:p=&quot;http://www.springframework.org/schema/p&quot;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:aop=&quot;http://www.springframework.org/schema/aop&quot;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:context=&quot;http://www.springframework.org/schema/context&quot;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:jee=&quot;http://www.springframework.org/schema/jee&quot;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:tx=&quot;http://www.springframework.org/schema/tx&quot;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:jaxws=&quot;http://cxf.apache.org/jaxws&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;xsi:schemaLocation=&quot;&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;http://www.springframework.org/schema/aop&nbsp;http://www.springframework.org/schema/aop/spring-aop-4.0.xsd&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;http://www.springframework.org/schema/beans&nbsp;http://www.springframework.org/schema/beans/spring-beans-4.0.xsd&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;http://www.springframework.org/schema/context&nbsp;http://www.springframework.org/schema/context/spring-context-4.0.xsd&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;http://www.springframework.org/schema/jee&nbsp;http://www.springframework.org/schema/jee/spring-jee-4.0.xsd&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;http://www.springframework.org/schema/tx&nbsp;http://www.springframework.org/schema/tx/spring-tx-4.0.xsd\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;http://cxf.apache.org/jaxws&nbsp;http://cxf.apache.org/schemas/jaxws.xsd&quot;&gt;</pre><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">这里的我是参考官方文档上，添加了 jaxws支持。。大家直接贴下即可；</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">然后我们再导入下cxf里的一些bean配置，参考官方文档：</p><pre class=\"brush:xml;toolbar:false\">&lt;import&nbsp;resource=&quot;classpath:META-INF/cxf/cxf.xml&quot;/&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&lt;import&nbsp;resource=&quot;classpath:META-INF/cxf/cxf-servlet.xml&quot;/&gt;</pre><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">（我看了cxf核心包，其实质疑偶cxf.xml，没有cxf-servlet.xml 估计是兼容前面版本）</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">我们把前面的类贴到我们这个项目了；</p><p style=\"white-space: normal;\"><img src=\"http://blog.java1234.com/static/userImages/20160316/1458107956835081125.jpg\" title=\"1458107956835081125.jpg\" alt=\"QQ鎴浘20160316135804.jpg\"/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">这里的HelloWorldImpl类上，我们加一个&nbsp;@Component(&quot;helloWorld&quot;) &nbsp;</p><p style=\"white-space: normal;\">Spring配置文件里，我加下扫描：</p><pre class=\"brush:xml;toolbar:false\">&lt;!--&nbsp;自动扫描&nbsp;--&gt;\n&lt;context:component-scan&nbsp;base-package=&quot;com.java1234.webservice&quot;&nbsp;/&gt;</pre><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">前面搞完后，我们在处理下web.xml文件 首先启动的时候，必须加载Spring：</p><pre class=\"brush:xml;toolbar:false\">&lt;!--&nbsp;Spring配置文件&nbsp;--&gt;\n&lt;context-param&gt;\n	&lt;param-name&gt;contextConfigLocation&lt;/param-name&gt;\n	&lt;param-value&gt;classpath:applicationContext.xml&lt;/param-value&gt;\n&lt;/context-param&gt;\n\n&lt;!--&nbsp;Spring监听器&nbsp;--&gt;\n&lt;listener&gt;\n	&lt;listener-class&gt;org.springframework.web.context.ContextLoaderListener&lt;/listener-class&gt;\n&lt;/listener&gt;</pre><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">然后我们要定义一个Servlet，主要是处理WebService请求：</p><pre class=\"brush:xml;toolbar:false\">&lt;servlet&gt;&nbsp;&nbsp;\n&nbsp;&lt;servlet-name&gt;CXFServlet&lt;/servlet-name&gt;&nbsp;&nbsp;\n&nbsp;&lt;servlet-class&gt;org.apache.cxf.transport.servlet.CXFServlet&lt;/servlet-class&gt;&nbsp;&nbsp;\n&lt;/servlet&gt;&nbsp;&nbsp;\n\n&lt;servlet-mapping&gt;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&lt;servlet-name&gt;CXFServlet&lt;/servlet-name&gt;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&lt;url-pattern&gt;/webservice/*&lt;/url-pattern&gt;&nbsp;&nbsp;\n&lt;/servlet-mapping&gt;</pre><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">这里的话，我们所有的 /webservice请求，都交给CXFServlet类处理；</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">最后一步，我们在Spring配置文件里，定义下webservice接口发布：<br/></p><pre class=\"brush:xml;toolbar:false\">&lt;!--&nbsp;定义服务提供者&nbsp;&nbsp;--&gt;\n&lt;jaxws:endpoint\n	implementor=&quot;#helloWorld&quot;\n	address=&quot;/HelloWorld&quot;\n&nbsp;&gt;&lt;/jaxws:endpoint&gt;</pre><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">这里implementor指定webservice接口实现类</p><p style=\"white-space: normal;\">address是具体的接口路径</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">最终完整的applicationContext.xml配置文件如下：</p><pre class=\"brush:xml;toolbar:false\">&lt;?xml&nbsp;version=&quot;1.0&quot;&nbsp;encoding=&quot;UTF-8&quot;?&gt;&nbsp;&nbsp;&nbsp;&nbsp;\n&lt;beans&nbsp;xmlns=&quot;http://www.springframework.org/schema/beans&quot;&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:p=&quot;http://www.springframework.org/schema/p&quot;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:aop=&quot;http://www.springframework.org/schema/aop&quot;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:context=&quot;http://www.springframework.org/schema/context&quot;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:jee=&quot;http://www.springframework.org/schema/jee&quot;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:tx=&quot;http://www.springframework.org/schema/tx&quot;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;xmlns:jaxws=&quot;http://cxf.apache.org/jaxws&quot;\n&nbsp;&nbsp;&nbsp;&nbsp;xsi:schemaLocation=&quot;&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;http://www.springframework.org/schema/aop&nbsp;http://www.springframework.org/schema/aop/spring-aop-4.0.xsd&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;http://www.springframework.org/schema/beans&nbsp;http://www.springframework.org/schema/beans/spring-beans-4.0.xsd&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;http://www.springframework.org/schema/context&nbsp;http://www.springframework.org/schema/context/spring-context-4.0.xsd&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;http://www.springframework.org/schema/jee&nbsp;http://www.springframework.org/schema/jee/spring-jee-4.0.xsd&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;http://www.springframework.org/schema/tx&nbsp;http://www.springframework.org/schema/tx/spring-tx-4.0.xsd\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;http://cxf.apache.org/jaxws&nbsp;http://cxf.apache.org/schemas/jaxws.xsd&quot;&gt;&nbsp;&nbsp;&nbsp;&nbsp;\n&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n	&lt;import&nbsp;resource=&quot;classpath:META-INF/cxf/cxf.xml&quot;/&gt;\n&nbsp;&nbsp;&nbsp;&nbsp;&lt;import&nbsp;resource=&quot;classpath:META-INF/cxf/cxf-servlet.xml&quot;/&gt;\n	\n&nbsp;&nbsp;&nbsp;&nbsp;&lt;!--&nbsp;自动扫描&nbsp;--&gt;\n	&lt;context:component-scan&nbsp;base-package=&quot;com.java1234.webservice&quot;&nbsp;/&gt;\n	\n	&lt;!--&nbsp;定义服务提供者&nbsp;&nbsp;--&gt;\n	&lt;jaxws:endpoint\n		implementor=&quot;#helloWorld&quot;\n		address=&quot;/HelloWorld&quot;\n	&nbsp;&gt;&lt;/jaxws:endpoint&gt;\n&lt;/beans&gt;</pre><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">我们来启动下项目，然后访问&nbsp;http://localhost:8080/WebService_CXF/webservice/&nbsp;</p><p style=\"white-space: normal;\">效果如下：</p><p style=\"white-space: normal;\"><img src=\"http://blog.java1234.com/static/userImages/20160316/1458108744475018549.jpg\" title=\"1458108744475018549.jpg\" alt=\"a.jpg\" width=\"711\" height=\"369\" style=\"width: 711px; height: 369px;\"/></p><p style=\"white-space: normal;\">说明已经webservice接口已经发布成功了；</p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">我们可以访问具体的接口：&nbsp;http://localhost:8080/WebService_CXF/webservice/HelloWorld?wsdl</p><p style=\"white-space: normal;\">效果如下：</p><p style=\"white-space: normal;\"><img src=\"http://blog.java1234.com/static/userImages/20160316/1458108937241033682.jpg\" title=\"1458108937241033682.jpg\" alt=\"b.jpg\"/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\">完整代码：<a href=\"http://pan.baidu.com/s/1nuhocNf\" target=\"_blank\" title=\"http://pan.baidu.com/s/1nuhocNf\">http://pan.baidu.com/s/1nuhocNf</a></p><p style=\"white-space: normal;\"><br/></p><p style=\"white-space: normal;\"><br/></p><p><br/></p>', 9, 'spring webservice cxf');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (71, 'Spring整合CXF之添加拦截器', '今天主要来讲解下如何在Spring整合CXF环境下，添加拦截器；这里我们给下官方的参考文档：http://cxf.apache.org/docs/jax-ws-configuration.html 结合官方文档，我们在前面的实例基础上，加代码：首先我们把前面的自定义拦截器 MyInterceptor 贴进来。', '2018-05-17 12:11:55', 210, 0, '<p>今天主要来讲解下如何在Spring整合CXF环境下，添加拦截器；</p><p><br/></p><p>这里我们给下官方的参考文档：<a href=\"http://cxf.apache.org/docs/jax-ws-configuration.html\" target=\"_blank\" title=\"http://cxf.apache.org/docs/jax-ws-configuration.html\">http://cxf.apache.org/docs/jax-ws-configuration.html</a> </p><p><br/></p><p>结合官方文档，我们在前面的实例基础上，加代码：</p><p><br/></p><p><img src=\"/static/userImages/20160317/1458187484241078987.jpg\" title=\"1458187484241078987.jpg\" alt=\"bbb.jpg\"/></p><p><br/></p><p>首先我们把前面的自定义拦截器 MyInterceptor 贴进来。</p><p><br/></p><p>然后我们打开spring配置文件，applicationContext.xml</p><p><br/></p><p>根据官方文档：我们通过jaxws:inInterceptors&nbsp;jaxws:outInterceptors 这两个标签来添加in拦截器和out拦截器</p><p><br/></p><p>我们修改下jaxws:endpoint 节点：</p><pre class=\"brush:xml;toolbar:false\">&lt;!--&nbsp;定义服务提供者&nbsp;&nbsp;--&gt;\n&lt;jaxws:endpoint\n	implementor=&quot;#helloWorld&quot;\n	address=&quot;/HelloWorld&quot;&gt;\n	&lt;!--&nbsp;添加in拦截器&nbsp;--&gt;\n	&lt;jaxws:inInterceptors&gt;\n		&nbsp;&lt;bean&nbsp;class=&quot;org.apache.cxf.interceptor.LoggingInInterceptor&quot;/&gt;\n		&nbsp;&lt;bean&nbsp;class=&quot;com.java1234.interceptor.MyInterceptor&quot;/&gt;\n	&lt;/jaxws:inInterceptors&gt;\n	&lt;!--&nbsp;添加out拦截器&nbsp;--&gt;\n	&lt;jaxws:outInterceptors&gt;\n		&nbsp;&lt;bean&nbsp;class=&quot;org.apache.cxf.interceptor.LoggingInInterceptor&quot;/&gt;\n	&lt;/jaxws:outInterceptors&gt;\n&lt;/jaxws:endpoint&gt;</pre><p><br/></p><p>这里 我们添加了两个in拦截器，一个是cxf自带的LogginInInterceptor拦截器，还有一个是我们自己定义的MyInterceptor拦截器，</p><p>主要用作权限判断；</p><p><br/></p><p>out拦截器，我们还是用了一个cxf自带的LogginInInterceptor拦截器；</p><p><br/></p><p>这样我们就完事了；我们可以看到。用spring我们可以很轻松的完整拦截器的配置；</p><p><br/></p><p>接下来测试下话，我们还是用前面开发的WS_Client来测试，因为请求的websercie地址变了。</p><p>所以我们用wsdl2java工具重新生成下新的客户端代码；（具体操作大家看前面的帖子，这里就不再重复叙述）</p><p><br/></p><p>我们测试的话，大家可以先把客户端的拦截器注释掉，我们会发现会报错，说找不到header消息；</p><p><br/></p><p>假如密码弄错，会报用户名或者密码不对；</p><p><br/></p><p>我们用正确的密码，webservice接口会返回正确的结果。</p><p><br/></p><p>OK。今天就到这里。</p><p><br/></p>', 9, 'webservice cxf 自定义拦截器');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (74, 'Spring source code', 'Spring源码深度解Spring技术内幕', '2018-07-03 10:51:31', 27, 0, '<pre class=\"brush:java;toolbar:false\">Spring源码深度解\nSpring技术内幕</pre>', 1, '');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (75, 'linux crontab 定时任务被重复执行多次问题', 'linux使用日志 今天检查定时任务发现 每个任务都被重复执行3次。检查发现crond服务在进程中有一模一样的3个。kill掉task id大的2个后正常。', '2018-07-14 16:55:00', 24, 0, '<p><span style=\"color: rgb(79, 79, 79); font-family: -apple-system, &quot;SF UI Text&quot;, Arial, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif, SimHei, SimSun; text-align: justify; background-color: rgb(255, 255, 255);\">linux使用日志&nbsp;</span><br style=\"box-sizing: border-box; outline: 0px; word-break: break-all; color: rgb(79, 79, 79); font-family: -apple-system, &quot;SF UI Text&quot;, Arial, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif, SimHei, SimSun; text-align: justify; white-space: normal; background-color: rgb(255, 255, 255);\"/><span style=\"color: rgb(79, 79, 79); font-family: -apple-system, &quot;SF UI Text&quot;, Arial, &quot;PingFang SC&quot;, &quot;Hiragino Sans GB&quot;, &quot;Microsoft YaHei&quot;, &quot;WenQuanYi Micro Hei&quot;, sans-serif, SimHei, SimSun; text-align: justify; background-color: rgb(255, 255, 255);\">今天检查定时任务发现 每个任务都被重复执行3次。检查发现crond服务在进程中有一模一样的3个。kill掉task id大的2个后正常。</span></p>', 13, '');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (76, 'mysqldump定时备份数据库', '书写bakmysql.sh#!/bin/bash # Name:bakmysql.sh# This is a ShellScript For Auto DB Backup and Delete old Backup # backupdir=~/mysqlbak time=` date +%Y%m%d%H%M%', '2018-07-16 16:58:14', 46, 0, '<p>书写</p><p>bakmysql.sh</p><p><br/></p><pre class=\"brush:bash;toolbar:false\">\n#!/bin/bash&nbsp;\n#&nbsp;Name:bakmysql.sh\n#&nbsp;This&nbsp;is&nbsp;a&nbsp;ShellScript&nbsp;For&nbsp;Auto&nbsp;DB&nbsp;Backup&nbsp;and&nbsp;Delete&nbsp;old&nbsp;Backup&nbsp;\n#&nbsp;\n\nbackupdir=~/mysqlbak&nbsp;\ntime=`&nbsp;date&nbsp;+%Y%m%d%H%M%S&nbsp;`\nmysqldump&nbsp;-u&nbsp;username&nbsp;-ppasswd&nbsp;db_blog&nbsp;|&nbsp;gzip&nbsp;&gt;&nbsp;$backupdir/name_1_db_name$time.sql.gz\nfind&nbsp;$backupdir&nbsp;-name&nbsp;&quot;name_*.sql.gz&quot;&nbsp;-type&nbsp;f&nbsp;-mtime&nbsp;+8&nbsp;-exec&nbsp;rm&nbsp;{}&nbsp;\\;&nbsp;&gt;&nbsp;/dev/null&nbsp;2&gt;&amp;1</pre><p>配置可执行权限</p><pre class=\"brush:bash;toolbar:false\">vim&nbsp;/etc/crontab</pre><p>添加上下一行内容</p><pre class=\"brush:bash;toolbar:false\">00&nbsp;3&nbsp;*&nbsp;*&nbsp;*&nbsp;root&nbsp;/root/bakmysql.sh</pre><pre class=\"brush:bash;toolbar:false\">crond&nbsp;restart</pre><p>crond重启失败</p><p>报错</p><p>crond: can&#39;t lock /var/run/crond.pid, otherpid may be 1426: Resource temporarily unavailable</p><p>解决方式，命令行执行shell</p><pre class=\"brush:bash;toolbar:false\">rm&nbsp;/var/run/crond.pid</pre><p>https://blog.csdn.net/luoww1/article/details/72677405</p><p><br/></p>', 13, '');
INSERT INTO `t_blog`(`id`, `title`, `summary`, `releaseDate`, `clickHit`, `replyHit`, `content`, `typeId`, `keyWord`) VALUES (77, 'Nginx + Tomcat HTTPS 配置', 'https://www.oschina.net/question/12_213459 nginx的配置文件的server节点中，增加listen       443 ssl;ssl_certificate  XXX.crtssl_certificate_key XXX.keylocationproxy_set', '2018-08-16 23:18:06', 39, 1, '<p><a href=\"https://www.oschina.net/question/12_213459\" _src=\"https://www.oschina.net/question/12_213459\">https://www.oschina.net/question/12_213459</a> </p><p><br/></p><p>nginx的配置文件的server节点中，增加</p><pre class=\"hljs shell nginx\" style=\"box-sizing: border-box; font-family: monospace, monospace; overflow-x: auto; padding: 0.5em; background-color: rgb(63, 63, 63); color: rgb(220, 220, 220);\">listen&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;443&nbsp;ssl;</pre><pre class=\"hljs shell nginx\" style=\"box-sizing: border-box; font-family: monospace, monospace; overflow-x: auto; padding: 0.5em; background-color: rgb(63, 63, 63); color: rgb(220, 220, 220);\">ssl_certificate&nbsp;&nbsp;XXX.crt</pre><pre class=\"hljs shell nginx\" style=\"box-sizing: border-box; font-family: monospace, monospace; overflow-x: auto; padding: 0.5em; background-color: rgb(63, 63, 63); color: rgb(220, 220, 220);\">ssl_certificate_key&nbsp;XXX.key</pre><p><br/></p><p><br/></p><p>location<br/></p><pre class=\"hljs shell nginx\" style=\"box-sizing: border-box; font-family: monospace, monospace; overflow-x: auto; padding: 0.5em; background-color: rgb(63, 63, 63); color: rgb(220, 220, 220);\">proxy_set_header&nbsp;X-Forwarded-Proto&nbsp;https;</pre><p><br/></p>', 3, '');
